import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  ImageBackground,
  ScrollView,
  SafeAreaView,
  FlatList,
  Image,
  RefreshControl
} from 'react-native';
import { Colors } from '../../Assets/Colors';
import { getIcon } from '../../Assets/Icon';
import Toolbar from '../../Component/Toolbar';
import { Metrics, Scale } from '../../utils/size';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import Buttons from '../../Component/Button';
import { Routers } from '../../utils/Routers';
import { getURL,postURL, deleteURL } from '../../utils/services/API';
import { Constants } from '../../utils/Constans';
import { getData } from '../../utils/Storage';
import { JSONAxioGet,JSONAxioDelete } from '../../utils/services/JsonService';

const VoucherScreen = ({route, navigation }) => {

  let [dataCod, setDataCod] = useState([
    {name : 'Discount 100% s/d 10 RB', nominal: '100%', desc: 'S&K Berlaku Berlaku 25-03-2023', icon: 'ic_foco_voucher', height: Scale(20), width: Scale(20)},
    {name : 'Discount ongkos kirim 100% s/d 10 RB', nominal: '100%', desc: 'S&K Berlaku Berlaku 25-03-2023', icon: 'ic_foco_voucher', height: Scale(20), width: Scale(20)},
    {name : 'Discount 100% s/d 10 RB', nominal: '100%', desc: 'S&K Berlaku Berlaku 25-03-2023', icon: 'ic_foco_voucher', height: Scale(20), width: Scale(20)},
    {name : 'Discount 100% s/d 10 RB', nominal: '100%', desc: 'S&K Berlaku Berlaku 25-03-2023', icon: 'ic_foco_voucher', height: Scale(20), width: Scale(20)}]);
  let [dataVoucher, setDataVoucher] = useState([])
  let [dataVoucherBuy, setDataVoucherBuy] = useState([])
  let [token, setToken] = useState(0)
  let [loading, setLoading] = useState(false)
  let [selectSendVoucher, setSelectSendVoucher] = useState(null)
  let [selectBuyVoucher, setSelectBuyVoucher] = useState(null)
  let [arrayData, setArrayData] = useState([])

  useEffect(() => {
    getdata()

  }, [token]);

  const goBack =(item)=>{
    // navigation.goBack()
        if(selectSendVoucher){
          navigation.navigate(Routers.CONFIRMATION_ORDER_PAGE, {voucher : route.params?.dataVoucher})
        } else {
          navigation.navigate(Routers.CONFIRMATION_ORDER_PAGE, {voucher : [{nama_voucher : 'Pilih Voucher', desc: 'S&K Berlaku Berlaku 25-03-2023', icon: 'ic_foco_voucher', height: Scale(20), width: Scale(20)}]})
        }
      
    
  }

  const getdata = () => {
    getData(Constants.SESSION_USER_PROFILE).then(res => {
      
      setToken(res.result.token)
      getListtVoucher();
     })
  }
  const selectSendBy =(item)=>{
    if (item?.kode_voucher == selectSendVoucher?.kode_voucher){
      setSelectSendVoucher(null)
    } else  {
      setSelectSendVoucher(item)
    }
    
    // navigation.navigate(Routers.CONFIRMATION_ORDER_PAGE, {voucher : item})
  }

  const selectBuy =(item)=>{
    if (item?.kode_voucher == selectBuyVoucher?.kode_voucher){
      setSelectBuyVoucher(null)
    } else  {
      setSelectBuyVoucher(item)
    }
    
    // navigation.navigate(Routers.CONFIRMATION_ORDER_PAGE, {voucher : item})
  }

  const useVoucher=()=>{    
    setArrayData([])
    var arrayData =[];

    if (selectSendVoucher){
      arrayData.push(selectSendVoucher)
    }

    if (selectBuyVoucher){
      arrayData.push(selectBuyVoucher)
    }

    setArrayData(arrayData)
    
    navigation.navigate(Routers.CONFIRMATION_ORDER_PAGE, {voucher : arrayData})
  }

  const getListtVoucher = (params) => {
    setLoading(true)
    setDataVoucher([])
    JSONAxioGet(getURL('api-list-voucher', null), null, token)
    .then(respone => {
      const response = respone.data;
      console.log(response.result.pengiriman)
      if (response.statusCode == "1") {
       
        
        if( route.params?.dataVoucher[0]?.nama_voucher != 'Pilih Voucher'){
          console.log("route.params?.dataVoucher >>>> ")
          console.log(route.params?.dataVoucher)
          setSelectSendVoucher(route.params?.dataVoucher[0])
        } else {
          setSelectSendVoucher(null)
        }
        setDataVoucher(response.result.pengiriman)
        setDataVoucherBuy(response.result.pembelian)
       
      } else {
       
      }

      setLoading(false);
    })
    .catch(error => {
      setLoading(false);
      console.log("error")
      console.log(error)
    });
  }


  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>

        <Toolbar
          onPress={goBack}
          title={'Gunakan Voucher'} /> 
        <View style={{ flex: 1, backgroundColor: Colors.gray }}>
          <ScrollView
           refreshControl={
            <RefreshControl refreshing={loading} onRefresh={getListtVoucher} />
          }>

            <Text style={{color: Colors.primaryColor, marginHorizontal: Scale(16), fontSize: Scale(16), fontWeight: 'bold'}}>Diskon Pengiriman </Text>
            <View style={{ flex: 1, backgroundColor: Colors.gray }}>
              {

                
               !loading && dataVoucher.map((item, i) => (
                  <View style={{ marginHorizontal: Scale(16), marginVertical: Scale(16), borderColor: (selectSendVoucher?.kode_voucher == item?.kode_voucher ? Colors.primaryColor : null), borderWidth: Scale(selectSendVoucher?.kode_voucher == item?.kode_voucher ? 1.5 : 0) }}>
                   
                    <TouchableOpacity
                      onPress={() => selectSendBy(item)}>
                      <View style={{}}>

                      <Image
                              style={{ height: Scale(70), width: Metrics.screenWidth/1.1}}
                              source={{uri: item.url_logo}}
                              resizeMethod='resize' />
                      </View>
                    </TouchableOpacity>
                    {/* </ImageBackground> */}
                  </View>
                ))
              }

            </View>

            {dataVoucherBuy.length > 0 && <Text style={{color: Colors.primaryColor, marginHorizontal: Scale(16), fontSize: Scale(16), fontWeight: 'bold'}}>Diskon Pembelian </Text>}
            <View style={{ flex: 1, backgroundColor: Colors.gray }}>
              {

                
                dataVoucherBuy.map((item, i) => (
                  <View style={{ marginHorizontal: Scale(16), marginVertical: Scale(16), borderColor: (selectBuyVoucher?.kode_voucher == item?.kode_voucher ? Colors.primaryColor : null), borderWidth: Scale(selectBuyVoucher?.kode_voucher == item?.kode_voucher ? 1.5 : 0) }}>
                   
                    <TouchableOpacity
                      onPress={() => selectBuy(item)}>
                      <View style={{}}>

                      <Image
                              style={{ height: Scale(70), width: Metrics.screenWidth/1.1}}
                              source={{uri: item.url_logo}}
                              resizeMethod='resize' />
                      </View>
                    </TouchableOpacity>
                    {/* </ImageBackground> */}
                  </View>
                ))
              }

            </View>
          </ScrollView>

          {(selectSendVoucher || selectBuyVoucher) &&<Buttons
              style={{ marginTop: Scale(16), marginHorizontal: Scale(16) }}
              onPress={() => {useVoucher()}}
              title={"Gunakan Voucher"} />}

        </View>

        </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default VoucherScreen;