// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView,
  Linking
} from 'react-native';
import { Colors } from '../../../../Assets/Colors';
import { getIcon } from '../../../../Assets/Icon';
import Toolbar from '../../../../Component/Toolbar';
import { Scale } from '../../../../utils/size';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import Buttons from '../../../../Component/Button';
import { Routers } from '../../../../utils/Routers';
import AddModal from '../../../../Component/AddModal';
import ModalConfirmationOrder from '../../../../Component/ModalConfirmationOrder';
import ModalConformationSendHub from '../../../../Component/ModalConformationSendHub';
import QRCode from 'react-native-qrcode-svg';
import { getData, removeData } from '../../../../utils/Storage';
import { Constants } from '../../../../utils/Constans';
import Loading from '../../../../Component/loading';
import PopUp from '../../../../Component/popUp';
import { getURLHub, postURL } from '../../../../utils/services/API';
import { JSONAxioGet, JSONAxioPost } from '../../../../utils/services/JsonService';

const DetilDokumenSerahTerimaScreen = ({route, navigation }) => {
  const [showModalConfirm, setShowModalConfirm] = useState(false);
  const [dataDetil, setDataDetil] = useState(null);
  let [isHub, setIsHub] = useState(null);
  let [loading, setLoading] = useState(false);
  let [warning, setWarning] = useState(false);
  let [contentWarning, setContentWarning] = useState(null);

    useEffect(() => {
      getData(Constants.SESSION_HUB).then(res => {
        setIsHub(JSON.parse(res).userRole)
      });

      setDataDetil(route.params?.data)
    }, [route.params]);

  const openSendBy =()=>{
    navigation.navigate(Routers.METODE_SEND, {})
  }

  const openPaymentMethode =()=>{
    navigation.navigate(Routers.PAYMENT_METODE, {})
  }

  const openVoucher =()=>{
    navigation.navigate( Routers.VOUCHER_SCREEN, {})
  }

  const openPressDetilPengiriman =(item)=>{

    setLoading(true);
    var params = {
      no_dpp : item.no_dpp
    }

    getData(Constants.SESSION_USER_PROFILE).then(res => {

      if (res) {
        JSONAxioGet(getURLHub(isHub !== "HUB" ? 'api_cohub_detail_dpp' : 'api-hub-detail-dpp', params), null, res.result.token)
          .then(respone => {
            setLoading(false);
            const response = respone.data;

            if (response.statusCode == 1) {

              var isArray = Array.isArray(response.result);
              var results = null;
              if (isArray) {
                results = response.result[0];
                console.log(">>>>>>><<<<<<")
                console.log(JSON.stringify(response.result))
              } else {
                results = response.result;
              }
              console.log(results)
              navigation.navigate( Routers.DETIL_PENGIRIMAN_SCREEN, {data: results})


            } else {

              cekError(response.statusCode, response.message);

            }
          })
          .catch(error => {
            setLoading(false);
            console.log("error")
            cekError(4, null);
          });
      }

    })

  }
  

  const goBack =(item)=>{
    navigation.goBack()
  }

  const onPressCall =()=>{
    Linking.openURL(`tel:${dataDetil?.phone_number}`)
  }

  const onPressWA =()=>{

    Linking.openURL('whatsapp://send?text=Hallo&phone='+dataDetil?.wa_number);
  }

  const onPresHubSendConfirm =()=>{

    var param = {
      "no_dst": dataDetil.no_dst
  }
  
  setLoading(true);
  
    getData(Constants.SESSION_USER_PROFILE).then(res => {
      JSONAxioPost(postURL(isHub === "HUB" ? 'api_hub_terima_dst' : route.params?.urlTakeOreder, null), param, res.result.token)
        .then(respone => {
          const response = respone?.data;

          setLoading(false);
          
          if (response?.statusCode == 1) {
            navigation.navigate(Routers.SUCCESS_SCREEN, { title: (isHub === "HUB" ? 'Berhasil Diterima' : 'Siap Diserahkan'), desc: (isHub === "HUB" ? 'Dokumen Serah Terima Berhasil Anda Terima Silakan Lanjutkan Proses Pengiriman' : 'Dokumen serah terima dalam proses menunggu untuk di ambil oleh hub'), titleButton: 'Dashboard' })
            // navigation.reset({ index: 0, routes: [{ name: Routers.SUCCESS_SCREEN }] });
          } else {
            cekError(response.statusCode, response.message);

          }
        })
        .catch(error => {
          setLoading(false);
          cekError(2, null);

        });

    });
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
        setContentWarning({
          title: "Oooops !!",
          desc: errorMessage,
          titleButton: "Login Kembali",
          statusCode: statusCode
        })
    } 
    else if (statusCode == 1){
      setContentWarning({
        title: "Yeey !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setLoading(false);
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  const actionButton = () => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: "LoginStack"}] });
        });
      });
    }
    
  }
  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>

        <Toolbar
        switchAccount={true}
        onPress={goBack}
        title={ route.params?.title } />

              <ScrollView>
                  <View style={{ flex: 1 }}>

                      <View style={{ paddingVertical: Scale(16), paddingHorizontal: Scale(16), borderBottomColor: Colors.gray, borderBottomWidth: Scale(2) }}>

                          <View style={{ flexDirection: 'row' }}>
                              <View style={{ flex: 0.7 }}>
                                  <Text style={{ color: Colors.black }}>{"No DST"}  </Text>
                              </View>

                              <View style={{ flex: 0.1 }}>
                                  <Text style={{ color: Colors.black }}>{":"}  </Text>
                              </View>

                              <View style={{ flex: 1 }}>
                                  <Text style={{ color: Colors.black }}>{dataDetil?.no_dst}</Text>
                              </View>

                          </View>

                          {isHub === "HUB" && <View style={{ flexDirection: 'row' }}>
                              <View style={{ flex: 0.7 }}>
                                  <Text style={{ color: Colors.black }}>{"No DPP"}  </Text>
                              </View>

                              <View style={{ flex: 0.1 }}>
                                  <Text style={{ color: Colors.black }}>{":"}  </Text>
                              </View>

                              <View style={{ flex: 1 }}>
                                  <Text style={{ color: Colors.black }}>{dataDetil?.no_dst}</Text>
                              </View>

                          </View>}

                          <View style={{ flexDirection: 'row' }}>
                              <View style={{ flex: 0.7 }}>
                                  <Text style={{ color: Colors.black }}>{isHub === "HUB" ? "Lokasi Pengambilan" : "Hub Penerima"}  </Text>
                              </View>

                              <View style={{ flex: 0.1 }}>
                                  <Text style={{ color: Colors.black }}>{":"}  </Text>
                              </View>

                              <View style={{ flex: 1 }}>
                                  <Text style={{ color: Colors.black }}>{dataDetil?.recipient_hub}</Text>
                              </View>

                          </View>

                          <View style={{ flexDirection: 'row' }}>
                              <View style={{ flex: 0.7 }}>
                                  <Text style={{ color: Colors.black }}>{"Jumlah DPP"}  </Text>
                              </View>

                              <View style={{ flex: 0.1 }}>
                                  <Text style={{ color: Colors.black }}>{":"}  </Text>
                              </View>

                              <View style={{ flex: 1 }}>
                                  <Text style={{ color: Colors.black }}>{dataDetil?.total_dpp}</Text>
                              </View>

                          </View>

                            {route.params?.showPhone && <View style={{ flexDirection: 'row', marginVertical: Scale(20) }}>
                              <View style={{ flex: 1 }}>
                                <TouchableOpacity
                                  onPress={() => onPressCall()}>
                                  <View style={{ backgroundColor: "#3BA2B9", height: Scale(40), marginHorizontal: Scale(16), justifyContent: 'center', alignItems: 'center' }}>
                                    <Image
                                      style={{ height: Scale(20), width: Scale(20), tintColor: Colors.white }}
                                      source={getIcon("ic_call")}
                                      resizeMode='contain' />
                                  </View>
                                </TouchableOpacity>
                              </View>

                              <View style={{ flex: 1 }}>
                                <TouchableOpacity
                                  onPress={() => onPressWA()}>
                                  <View style={{ backgroundColor: "#25D366", height: Scale(40), marginHorizontal: Scale(16), justifyContent: 'center', alignItems: 'center' }}>
                                    <Image
                                      style={{ height: Scale(20), width: Scale(20), tintColor: Colors.white }}
                                      source={getIcon("ic_wa")}
                                      resizeMode='contain' />
                                  </View>
                                </TouchableOpacity>
                              </View>

                            </View>}
                      </View>

                      <View style={{ paddingVertical: Scale(16), borderBottomColor: Colors.gray, borderBottomWidth: Scale(2) }}>
                      
                          <View style={{ flexDirection: 'row', backgroundColor:Colors.gray, borderBottomColor: Colors.gray, borderBottomWidth: Scale(1) }}>
                              <View style={{ flex: 0.5,  marginRight: Scale(2), paddingBottom: Scale(8), paddingHorizontal: Scale(8), backgroundColor:Colors.white, justifyContent:"center", alignItems: 'center'}}>
                                  <Text style={{ color: Colors.black }}>{"No"}  </Text>
                              </View>

                              <View style={{ flex: 1,  marginRight: Scale(2), paddingBottom: Scale(8), paddingHorizontal: Scale(8), backgroundColor:Colors.white, justifyContent:"center", alignItems: 'center'}}>
                                  <Text style={{ color: Colors.black }}>{"Dokumen Pengiriman Pesanan"}  </Text>
                              </View>

                              <View style={{ flex: 1,  marginRight: Scale(2), paddingBottom: Scale(8), paddingHorizontal: Scale(8), backgroundColor:Colors.white, justifyContent:"center", alignItems: 'center' }}>
                                  <Text style={{ color: Colors.black }}>{"Nama Pemesan"}</Text>
                              </View>

                              <View style={{ flex: 1, paddingHorizontal: Scale(2), paddingBottom: Scale(8), backgroundColor:Colors.white, justifyContent:"center", alignItems: 'center' }}>
                                  <Text style={{ color: Colors.black }}>{"Action"}</Text>
                              </View>

                          </View>

                          {dataDetil?.list_dpp.map((item, i) =>
                          (<View style={{ flexDirection: 'row', backgroundColor:Colors.gray }}>
                          <View style={{ flex: 0.5,  marginRight: Scale(2), paddingHorizontal: Scale(8), backgroundColor:Colors.white, justifyContent:"center", alignItems: 'center'}}>
                              <Text style={{ color: Colors.black }}>{i+1}  </Text>
                          </View>

                          <View style={{ flex: 1,  marginRight: Scale(2), paddingHorizontal: Scale(8), paddingVertical:Scale(8), backgroundColor:Colors.white, justifyContent:"center", alignItems: 'center'}}>
                              <Text style={{ color: Colors.black }}>{item.no_dpp}  </Text>
                          </View>

                          <View style={{ flex: 1,  marginRight: Scale(2), paddingHorizontal: Scale(8), paddingVertical:Scale(8), backgroundColor:Colors.white, justifyContent:"center", alignItems: 'center' }}>
                              <Text style={{ color: Colors.black }}>{item.customer_name}</Text>
                          </View>

                          <View style={{ flex: 1, paddingHorizontal: Scale(2), paddingVertical:Scale(8), backgroundColor:Colors.white, justifyContent:"center", alignItems: 'center' }}>
                              <TouchableOpacity
                              onPress={() => openPressDetilPengiriman(item)}>
                              <Text style={{ color: Colors.primaryColorHub }}>{"Detail"}</Text>
                              </TouchableOpacity>
                          </View>

                      </View>)
                          )}
                      
                      </View>
                    
                        {/* IF Co Hub This Is Show */}
                      <View style={{ justifyContent: 'center', alignItems: 'center', marginTop: Scale(18) }}>

                          {route.params?.qrCode && <Text style={{ color: Colors.black, marginVertical: Scale(8), fontSize: Scale(16) }}>{"Hub Scan Disini"}</Text>}

                         {route.params?.qrCode &&  <QRCode
                              size={Scale(80)}
                              value={dataDetil?.no_dst.toString()}
                          />}

                          {route.params?.qrCode && < Text style={{ color: Colors.primaryColorHub, marginVertical: Scale(16) }}>{dataDetil?.no_dst}</Text>}
                      </View>

                    
                      <Text style={{ color: Colors.black, margin: Scale(16) }}>{"Periksa kembali barang untuk memastikan tidak ada kesalahan barang dan jumlah dalam DO ini"}</Text>

                      <View style={{  marginVertical: Scale(16),marginHorizontal: Scale(16), }}>
                          {dataDetil?.recipient_button && <Buttons
                              onPress={() => onPresHubSendConfirm()}
                              switchAccount={true}
                              title={(route.params?.titleButtonDetil ? route.params?.titleButtonDetil : "Konfirmasi Penyerahan")} />}

                            {/* if Hub Disable */}
                          {(route.params?.showOtherButton && dataDetil?.recipient_button) && <Buttons
                              style={[{ backgroundColor: Colors.white, borderColor: Colors.primaryColorHub, borderWidth: Scale(1) }]}
                              styleTitle={{ color: Colors.primaryColorHub }}
                              onPress={() => console.log("")}
                              switchAccount={true}
                              title={( "Alihkan Ke Hub Yang Lain")} />}
                      </View>

            <Loading
              visible={loading} />

            <PopUp
              visible={warning}
              onPressButton={() => { actionButton() }}
              title={contentWarning?.title}
              desc={contentWarning?.desc}
              titleButton={contentWarning?.titleButton} />
                  </View>
              </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default DetilDokumenSerahTerimaScreen;