// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  StyleSheet,
  View,
  Text,
  Image,
  FlatList,
  TouchableOpacity
} from 'react-native';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import { Metrics, Scale } from '../../../../utils/size';
import { Colors } from '../../../../Assets/Colors';
import { getIcon } from '../../../../Assets/Icon';
import { Routers } from '../../../../Constansutils/Routers';
import { getData } from '../../../../utils/Storage';
import { Constants } from '../../../../utils/Constans';
import Buttons from '../../../../Component/Button';

const ItemOrder = ({ navigation, data, onPress, titleButton, titleButtonDetil, onPressCheckBox,checkBoxActive, tabFlag }) => {
  let [menu, setMenu] = useState([
    {name : 'Pesanan Baru', icon: 'ic_new_order'}, 
    {name : 'Ambil Pesanan', icon: 'ic_new_send'},
    {name : 'Order Retur', icon: 'ic_retur_order'},
    {name : 'Finance', icon: 'ic_finance'},
    {name : 'Inventory', icon: 'ic_inventory'},
    {name : 'Logistik', icon: 'ic_logistic'}, 
  ]);

  let [hub, setHub] = useState(true)
 

  useEffect(() => {

    getData(Constants.SESSION_HUB).then(res => {
     if (res){

       if (JSON.parse(res).userRole === "HUB"){
        setHub(true)

       } else if (JSON.parse(res).userRole === "COHUB") {
        setHub(false)
       }

     } else {
      
     }
    })
 }, []);
 
 const titleButtons =()=>{
  
  if (tabFlag == 1){
    return 'Lihat Detail DST'
  } else if (tabFlag == 2){
    return 'Lihat Setoran'
  }else if (tabFlag == 3){
    return 'Siap Disetorkan'
  } else if (tabFlag == 4){
    return 'Lihat Setoran'
  } else if (tabFlag == 5){
    return 'Lihat Setoran'
  } else if (tabFlag == 6){
    return 'Lihat Setoran'
  }
  else if (tabFlag == 7){
    return 'Lanjutkan Setoran'
  }
 }

 const bgColorsButtons =()=>{
  
  if (tabFlag == 1){
    return Colors.white
  } else if (tabFlag == 2){
    return Colors.white
  } else if (tabFlag == 3){
    return Colors.primaryColorHub
  } else if (tabFlag == 4){
    return Colors.primaryColorHub
  } else if (tabFlag == 5){
    return Colors.white
  }else if (tabFlag == 7){
    return Colors.white
  }
 }
 const titleColorsButtons =()=>{
  
  if (tabFlag == 1){
    return Colors.primaryColorHub
  } else if (tabFlag == 2){
    return Colors.primaryColorHub
  } else if (tabFlag == 3){
    return Colors.white
  } else if (tabFlag == 4){
    return Colors.white
  } else if (tabFlag == 5){
    return Colors.primaryColorHub
  }else if (tabFlag == 6){
    return Colors.primaryColorHub
  }else if (tabFlag == 7){
    return Colors.primaryColorHub
  }
 }

 const titleSatu =()=>{
  
  if (tabFlag == 1){
    return "Nomor Setoran"
  } else if (tabFlag == 2){
    return "Nomor Setoran Hub"
  } else if (tabFlag == 3){
    return "Nomor Setoran Cohub"
  } else if (tabFlag == 4){
    return "Nomor Setoran Cohub"
  } else if (tabFlag == 5){
    return "Nomor Setoran Cohub"
  } else if (tabFlag == 6){
    return "Nomor Setoran Cohub"
  }else if (tabFlag == 7){
    return "Nomor Setoran Cohub"
  }
  
 }

 const titleTiga =(tabFlag)=>{
  if (tabFlag == 3){
    return "Tanggal Dibuat"
  } else if (tabFlag == 4){
    return "Tanggal Konfirmasi"
  } else if (tabFlag == 5){
    return "Tanggal Ditolak"
  }  else if (tabFlag == 6){
    return "Tanggal Konfirmasi"
  } else {
    return null
  }
 }

 const valueTitleTiga =(tabFlag,item)=>{
  if (tabFlag == 3){
    return item?.tanggalDibuat
  } else if (tabFlag == 4){
    return item?.tanggalKonfirmasi
  } else if (tabFlag == 5){
    return item?.tanggalDibuat
  }  else if (tabFlag == 6){
    return item?.tanggalDibuat
  }
 }

  return (
      <View style={{flex :1, backgroundColor: Colors.white, padding: Scale(8), paddingHorizontal: Scale(16), marginVertical: Scale(8),  }}>
        
      {tabFlag == 7 && <View>
        <Text style={[styles.text40012, { color: Colors.red, fontSize: Scale(12), marginVertical: Scale(2), textAlign: 'center' }]}>{"Batas waktu Penyetoran"}</Text>
        <Text style={[styles.text40012, { color: Colors.red, fontSize: Scale(20), marginVertical: Scale(2), textAlign: 'center' }]}>{"00:00:00"}</Text>
      </View>}
        
        <View style={{ flexDirection: 'row'}}>
          {(tabFlag < 3 )&& <View style={{ flex: 0.1, paddingTop: Scale(14)}}>
            <TouchableOpacity
            onPress={() => onPressCheckBox(data)}>
             <Image
              style={{ height: Scale(20), width: Scale(20) }}
              source={getIcon(checkBoxActive ? 'ic_check_box_hub' : 'ic_check_box_blank_hub')}
              resizeMode='contain' />
            </TouchableOpacity>
          </View>}
          <View style={{ flex: 1 }}>

            <View style={{ flexDirection: 'row', marginVertical: Scale(4) }}>
             
              <View style={{ flex: 1 }}>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{titleSatu()}</Text>
                {tabFlag >= 4 && <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{tabFlag == 7 ?  "Tanggal Dibuat":"Tanggal Disetorkan"}</Text>}
                {titleTiga(tabFlag) && <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{titleTiga(tabFlag)}</Text>}
                {tabFlag < 2 && <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{"Nama dan ID HUB"}</Text>}
                {tabFlag < 3 &&  <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{tabFlag <= 3 ? "Jumlah DST" : "Jumlah HUB"}</Text>}
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8)  }]}>{"Total Nilai"}</Text>
              </View>

              <View style={{ flex: 1, alignItems:'flex-end' }}>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{data?.idSetoranHub ? data?.idSetoranHub : data?.idSetoranCoHub}</Text>
                {tabFlag >= 4 && <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{data?.tanggalDibuat}</Text>}
                {titleTiga(tabFlag) && <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{valueTitleTiga(tabFlag, data)}</Text>}
                {tabFlag < 2 && <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{data?.namaHub ? data?.namaHub : '-'}</Text>}
                {tabFlag < 3 && <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8)  }]}>{data?.totalDst ? data?.totalDst : data?.totalHub}</Text>}
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{data?.nilaiCod}</Text>
              </View>
            </View>

          </View>


        </View>
        
      <Buttons
        style={[{ backgroundColor: bgColorsButtons(), borderColor: Colors.primaryColorHub, borderWidth: Scale(1) }]}
        styleTitle={{ color: titleColorsButtons() }}
        onPress={() => onPress()}
        switchAccount={true}
        title={(titleButtons())} />

      </View>
  );
}

const styles = StyleSheet.create({
  container: {flex:1},
  containerRow: { flexDirection: 'row' },
  imgRow: { height: Scale(40), width: Scale(40) },
  viewCenter: { flex: 1, justifyContent: 'center' },
  viewCenterPadding: { paddingLeft: Scale(16), paddingRight: Scale(16) },
  text600: { color: Colors.black, fontWeight: '600', fontSize: Scale(14) },
  text60012: { color: Colors.black, fontWeight: '600', fontSize: Scale(12) },
  text40012: { color: Colors.black, fontWeight: '400', fontSize: Scale(12) },
  text40014: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
  viewRowSaldo: { flexDirection: 'row', height: Scale(60), backgroundColor: Colors.gray, marginVertical: Scale(8), borderRadius: Scale(10), padding: Scale(10) }

});
export default ItemOrder;