// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  StyleSheet,
  View,
  Text,
  Image,
  FlatList,
  TouchableOpacity
} from 'react-native';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import { Metrics, Scale } from '../../../../utils/size';
import { Colors } from '../../../../Assets/Colors';
import { getIcon } from '../../../../Assets/Icon';
import { Routers } from '../../../../Constansutils/Routers';
import { getData } from '../../../../utils/Storage';
import { Constants } from '../../../../utils/Constans';
import Buttons from '../../../../Component/Button';

const ItemOrder = ({ navigation, data, onPress, titleButton, titleButtonDetil, onPressCheckBox,checkBoxActive, tabFlag,search }) => {
  let [menu, setMenu] = useState([
    {name : 'Pesanan Baru', icon: 'ic_new_order'}, 
    {name : 'Ambil Pesanan', icon: 'ic_new_send'},
    {name : 'Order Retur', icon: 'ic_retur_order'},
    {name : 'Finance', icon: 'ic_finance'},
    {name : 'Inventory', icon: 'ic_inventory'},
    {name : 'Logistik', icon: 'ic_logistic'}, 
  ]);

  let [hub, setHub] = useState(true)

  useEffect(() => {

    getData(Constants.SESSION_HUB).then(res => {
     if (res){

       if (JSON.parse(res).userRole === "HUB"){
        setHub(true)

       } else if (JSON.parse(res).userRole === "COHUB") {
        setHub(false)
       }

     } else {
      
     }
    })
 }, []);

  return (
      <View style={{flex :1, backgroundColor: Colors.white, padding: Scale(8), paddingHorizontal: Scale(16), marginVertical: Scale(8),  }}>
        <View style={{ flexDirection: 'row'}}>
          {tabFlag !== 3 && <View style={{ flex: 0.1, paddingTop: Scale(14)}}>
            <TouchableOpacity
            onPress={() => onPressCheckBox(data)}>
             <Image
              style={{ height: Scale(20), width: Scale(20) }}
              source={getIcon(checkBoxActive ? 'ic_check_box_hub' : 'ic_check_box_blank_hub')}
              resizeMode='contain' />
            </TouchableOpacity>
          </View>}
          <View style={{ flex: 1 }}>

            <View style={{ flexDirection: 'row', marginVertical: Scale(4) }}>
             
              <View style={{ flex: 1 }}>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{'Nomor DST'}</Text>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{"COHUB Penerima"}</Text>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{"Jumlah DPP"}</Text>
                {search && <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8)  }]}>{"DPP Selesai"}</Text>}
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{"Total Nilai"}</Text>
                {search && <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{"Sudah Disetor"}</Text>}
                {search && <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8)}]}>{"Siap Diserahkan"}</Text>}
              </View>

              <View style={{ flex: 1, alignItems:'flex-end' }}>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{search ? (data?.no_dst ? data?.no_dst : "-") : (data?.noDst ? data?.noDst : "-")}</Text>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{search ?  (data?.nama_cohub ? data?.nama_cohub : '-') : (data?.namaCoHub ? data?.namaCoHub : '-')}</Text>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8)  }]}>{search ? (data?.total_dpp ? data?.total_dpp : '-') : (data?.totalDpp ? data?.totalDpp : '-')}</Text>
                {search && <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{data?.dpp_selesai}</Text>}
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{data?.nilaiCod ? data?.nilaiCod : '-'}</Text>
                {search &&  <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{data?.sudah_disetor ? data?.sudah_disetor : '-'}</Text>}
                {search &&  <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{data?.siap_disetor ? data?.siap_disetor : '-'}</Text>}
              </View>
            </View>

          </View>


        </View>
        
      <Buttons
        style={[{ backgroundColor: Colors.white, borderColor: Colors.primaryColorHub, borderWidth: Scale(1) }]}
        styleTitle={{ color: Colors.primaryColorHub }}
        onPress={() => onPress()}
        switchAccount={true}
        title={("Lihat Detail")} />

      </View>
  );
}

const styles = StyleSheet.create({
  container: {flex:1},
  containerRow: { flexDirection: 'row' },
  imgRow: { height: Scale(40), width: Scale(40) },
  viewCenter: { flex: 1, justifyContent: 'center' },
  viewCenterPadding: { paddingLeft: Scale(16), paddingRight: Scale(16) },
  text600: { color: Colors.black, fontWeight: '600', fontSize: Scale(14) },
  text60012: { color: Colors.black, fontWeight: '600', fontSize: Scale(12) },
  text40012: { color: Colors.black, fontWeight: '400', fontSize: Scale(12) },
  text40014: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
  viewRowSaldo: { flexDirection: 'row', height: Scale(60), backgroundColor: Colors.gray, marginVertical: Scale(8), borderRadius: Scale(10), padding: Scale(10) }

});
export default ItemOrder;