// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  FlatList,
  StyleSheet,
  View,
  SafeAreaView,
  ToastAndroid,
  TouchableOpacity,
  Dimensions,
  TextInput,
  PermissionsAndroid
} from 'react-native';
import { getDeviceId, getSystemVersion } from 'react-native-device-info';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import { Colors } from '../../Assets/Colors';
import Banner from './Banner/';
import Account from '../ProfileScreen/Profile/Account';
import Location from './Location';
import Content from './Content';
import AddModal from '../../Component/AddModal';
import { Constants } from '../../utils/Constans';
import { getData, removeData, storeData } from '../../utils/Storage';
import HubScreen from './HubScreen';
import { JSONAxioGet, JSONAxioPostFile } from '../../utils/services/JsonService';
import { getURL, getURLHub, postURL } from '../../utils/services/API';
import { Toaster, ToasterHelper } from 'react-native-customizable-toast';
import { Routers } from '../../utils/Routers';
import { Scale } from '../../utils/size';
import PopUp from '../../Component/popUp';
import useBackHandler from '../../utils/UseBackHandler/useBackHandler';
import GetLocation from 'react-native-get-location'
import messaging from '@react-native-firebase/messaging';
import notifee, { AndroidImportance } from '@notifee/react-native';
import Notifee from '../../utils/Notifee';


import PopUpCheckVersion from '../../Component/PopUpCheckVersion';
import { Eng } from '../../utils/String';
const { width } = Dimensions.get('window')

const HomeScreen = ({ navigation }) => {

  const [showModal, setShowModal] = useState(false);
  let [switchAccount, setswitchAccount] = useState(false);
  let [login, setLogin] = useState(null);
  let [dataCoint, setDataCoint] = useState({ focoCoint: "0", focoPoint: "0", saldo: "0", totalReferal: 0 });
  let [listProduct, setListProduct] = useState(null);
  let [listProductHub, setListProductHub] = useState([]);
  let [isHub, setIsHub] = useState(null);
  let [loading, setLoading] = useState(false);
  let [dataItem, setDataItem] = useState(null);
  let [searchActive, setSearchActive] = useState(false);
  let [search, setSearch] = useState("");
  let [warning, setWarning] = useState(false);
  let [contentWarning, setContentWarning] = useState(null);
  let [token, setToken] = useState(null);
  let [locations, setLocation] = useState(null);
  let [modalCheckVersion, setModalCheckVersion] = useState(false);
  let [contentCheckVersion, setContentCheckVersion] = useState(null);


  useEffect(() => {

    checkPermision()



  }, []);



  const checkPermision = async () => {




    try {
      const granted = await PermissionsAndroid.check(PermissionsAndroid.PERMISSIONS.ACCESS_FINE_LOCATION);

      if (granted) {
        GetLocation.getCurrentPosition({
          enableHighAccuracy: true,
          timeout: 60000,
        })
          .then(location => {
            setLocation(location)
            getDataList(location)
            console.log(location);
          })
          .catch(error => {
            const { code, message } = error;
            getDataList(null);
            console.warn(code, message);
          })

      } else {
        const granted = await PermissionsAndroid.request(
          PermissionsAndroid.PERMISSIONS.ACCESS_FINE_LOCATION
        )
        getDataList(null);
      }
    } catch (err) {
      console.warn(err)
      getDataList(null);
    }
  }

  const getDataList = (location) => {

    getData(Constants.SESSION_HUB).then(res => {

      if (res) {
        if (JSON.parse(res).userRole === "HUB" || JSON.parse(res).userRole === "COHUB") {
          setIsHub(JSON.parse(res).userRole)
          setswitchAccount(true);

          getdataHubCohub("");
        } else {
          setswitchAccount(false);
          getdata("", location);
        }
      } else {
        setswitchAccount(false);
        getdata("", location);
      }

    });
  }

  const showModals = (item) => {
    setShowModal(true);
    setDataItem(item);
  }

  const getdataHubCohub = (search) => {

    getData(Constants.SESSION_USER_PROFILE).then(res => {


      var params = {
        userid: res ? res.result.hp : '0'
      }
      if (res) {
        setToken(res.result.token)
        getPoint(params, res.result.token, res);

      }




      getData(Constants.SESSION_HUB).then(rest => {

        if (JSON.parse(rest).userRole === "HUB") {
          var paramsListProduct = {
            search: search,
            pagination: 1,
            status: 1,
            hubLocation: ''
          }

          getListProductHub(paramsListProduct, res.result.token);
        }

        if (JSON.parse(rest).userRole === "COHUB") {

          var paramsListProduct = {
            search: search,
            status: 0,
            hubLocation: ''
          }

          getListProductCoHub(paramsListProduct, res.result.token);
        }
      });


    })
  }
  const getdata = (search, location) => {

    getData(Constants.SESSION_USER_PROFILE).then(res => {


      var params = {
        userid: res ? res.result.hp : '0',
        lat: location?.latitude,
        long: location?.longitude
      }
      if (res) {
        console.log("<<<< LOCATION >>>> ");
        console.log(JSON.stringify(location))
        console.log(" <<<<< >>>>>");
        console.log(JSON.stringify(params))
        getPoint(params, res.result.token, res);
      }

      let systemVersion = getSystemVersion();

      var paramsListProduct = {
        search: search,
        pagination: 1,
        hubLocation: '',
        os_version: "android_" + systemVersion,
        version: Eng.VERSION
      }
      getListProduct(paramsListProduct);
    })
  }

  const getPoint = (params, token, res) => {
    setLoading(true);
    JSONAxioGet(getURL('get-coint', params), null, token)
      .then(respone => {
        const response = respone.data;
        setLoading(false);

        if (response.statusCode == 1) {
          console.log("response.result >>>>> ")
          console.log(response.result)
          console.log("<<<<>>>>")
          console.log(JSON.stringify(res))
          console.log("<<<<>>>>")
          res.result.saldo = response.result.saldo
          res.result.focoPoint = response.result.focoPoint
          res.result.focoCoint = response.result.focoPoint
          setLogin(res);
          storeData(Constants.SESSION_USER_PROFILE, res);
          setDataCoint(response.result);
        } else {
          cekError(response.statusCode, response.message)
        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }

  const getListProduct = (params) => {
    JSONAxioGet(getURL('get-list-product', params), null, null)
      .then(respone => {
        setLoading(false);
        const response = respone.data;
        console.log("Respon 1111 >>>>")
        console.log(response)
        if (response.statusCode == 1) {
          if (Eng.VERSION !== response.version) {
            setModalCheckVersion(true)
            setContentCheckVersion(response)
            setListProduct(response.result);
          } else {
            setListProduct(response.result);
          }
        } else {
          console.log("Respon >>>>")
          console.log(JSON.stringify(response));

          if (Eng.VERSION !== response.version) {
            setModalCheckVersion(true)
            setContentCheckVersion(response)
          } else {
            cekError(response.statusCode, response.message);
          }

        }
      })
      .catch(error => {
        setLoading(false);
        console.log(JSON.stringify(error));

        cekError(600, "Maaf sedang ada gangguan silakan hubungi Customer Service Kami Atau cek koneksi internet Anda")
      });
  }

  const getListProductHub = (params, token) => {
    setListProductHub([])
    JSONAxioGet(getURLHub('get-list-product-hub', params), null, token)
      .then(respone => {
        setLoading(false);
        const response = respone.data;
        if (response.statusCode == 1) {
          setListProductHub(response.result);
        } else {

          cekError(response.statusCode, response.message);

        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }

  const getListProductCoHub = (params, token) => {
    JSONAxioGet(getURLHub('api-cohub-list-dst', params), null, token)
      .then(respone => {
        setLoading(false);
        const response = respone.data;
        if (response.statusCode == 1) {
          setListProductHub(response.result);
        } else {

          cekError(response.statusCode, response.message);

        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }

  const addCart = (total, idProduct) => {


    if (login) {
      var param = {
        id_item_produk: idProduct,
        totalPesanan: total
      }

      var token = login ? login.result.token : null;

      JSONAxioPostFile(postURL('add_cart'), param, token)
        .then(respone => {
          const response = respone.data;
          // setLoading(false);
          if (response.statusCode == 1) {
            setShowModal(false)
            cekError(response.statusCode, response.message);
          } else {

            cekError(response.statusCode, response.message);

          }
        })
        .catch(error => {
          // setLoading(false);
          console.log("error")
          console.log(error)

        });
    } else {

      cekError(0, 'Silakan Login untuk melakukan transaksi.');

    }

  }


  const searchListProduct = (searchs) => {

    setSearch(searchs)


    if (searchs.length > 3) {
      if (isHub === "HUB" || isHub === "COHUB") {
        getdataHubCohub(searchs)
      } else {
        getdata(searchs, locations)
      }

    }
    if (searchs.length == 0) {
      if (isHub === "HUB" || isHub === "COHUB") {
        getdataHubCohub(searchs)
      } else {
        getdata(searchs, locations)
      }
    }

  }

  const closeSearchListProduct = () => {
    setSearch(null)
    setSearchActive(false)
    getdata("", locations)
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "Login Kembali",
        statusCode: statusCode
      })
    }
    else if (statusCode == 1) {
      setContentWarning({
        title: "Yeey !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setLoading(false);
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  const actionButton = () => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: "LoginStack" }] });
        });
      });
    }

  }

  return (
    <SafeAreaView style={styles.safeArea}>
      <Notifee />
      {searchActive && <View style={{ justifyContent: 'center', alignItems: 'center', height: Scale(80), backgroundColor: Colors.greenWhite }}>
        <View style={styles.containersViewRow}>
          <View style={styles.viewText}>
            <TextInput
              value={search}
              onChangeText={value => searchListProduct(value)}
              style={{ padding: Scale(8) }}
              placeholder={"Cari beragam kebutuhan keseharian"} />
          </View>
          <TouchableOpacity
            style={styles.viewIcon}
            onPress={() => { closeSearchListProduct() }}>
            <View >
              <FontAwesome
                name={'times-circle'}
                size={20}
                color={Colors.grayIcon}
              />
            </View>
          </TouchableOpacity>
        </View>
      </View>}

      <FlatList
        style={{ flex: 1, backgroundColor: Colors.greenWhite }}
        refreshing={loading}
        onRefresh={() => { isHub ? getdataHubCohub(search) : getdata(search) }}
        data={['']}
        renderItem={({ item }) =>
        (
          <View
            style={styles.container}>

            {!searchActive && <View>
              <Banner
                onPressSearch={() => { setSearchActive(!searchActive) }} />


              {login && <Account
                key={0}
                onPresSwitch={() => { console.log("") }}
                dataCoint={dataCoint}
                switchAccount={switchAccount}
                navigation={navigation} />}


            </View>
            }
            {/* {!switchAccount && <Location />} */}

            {switchAccount &&
              <HubScreen
                searchActive={searchActive}
                navigation={navigation}
                token={token}
                newsOrder={listProductHub} />}

            {(!switchAccount && listProduct) && <Content

              dataListProduct={listProduct}
              login={login}
              onPress={(item) => showModals(item)} />}
          </View>)
        }
      />
      {showModal && <AddModal
        addButton={(total, idProduct) => addCart(total, idProduct)}
        data={dataItem}
        onCloses={() => setShowModal(false)}
        kodeSupplier={dataItem.supplier.kode_supplier}
        ShowComment={showModal} />}

      <PopUpCheckVersion
        visible={modalCheckVersion}
        onPressButton={() => { setModalCheckVersion(false) }}
        contentCheckVersion={contentCheckVersion} />


      <PopUp
        visible={warning}
        onPressButton={() => { actionButton() }}
        title={contentWarning?.title}
        desc={contentWarning?.desc}
        titleButton={contentWarning?.titleButton} />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: Colors.greenWhite
  },
  safeArea: {
    flex: 1
  },
  containersView: { width: width, position: 'absolute', alignItems: 'center', justifyContent: 'center', padding: Scale(30) },
  containersViewRow: { flexDirection: 'row', height: Scale(60), width: Scale(300), borderRadius: Scale(30), backgroundColor: Colors.white, alignItems: 'center' },
  viewIcon: { flex: 0.1, padding: Scale(10) },
  viewText: { flex: 1, padding: Scale(10) },
  image: {
    width,
    flex: 1

  },
});
export default HomeScreen;