// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import * as React from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView
} from 'react-native';
import { Colors } from '../../../../Assets/Colors';
import { getIcon } from '../../../../Assets/Icon';
import { Scale } from '../../../../utils/size';
import { currency } from '../../../../utils/General';

const ItemOrder = ({ navigation, onPress, data }) => {
  return (
     
    <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
    
    <View style={{ flexDirection: 'row' }}>
      <View style={{ flex: 0.4 }}>
        <Image
          style={{
            width: Scale(80),
            height: Scale(80),
            borderRadius: Scale(8)

          }}
          source={{
            uri: data?.image_url ? data?.image_url : data?.url_gambar_sku
          }}
          resizeMode="stretch"
        />

      </View>

      <View style={{ flex: 1 }}>
        <Text style={{ color: Colors.black, fontWeight: '600' }}>{data?.product_name ? data?.product_name : data?.nama_produk}</Text>

        <View style={{ flexDirection: 'row', marginVertical: Scale(8) }}>
          <View style={{ flex: 1 }}>
            <Text style={{ color: Colors.black, fontWeight: '300' }}>{data?.size ? data?.size : data?.nama_ukuran}</Text>
          </View>
          <View style={{ flex: 1, alignItems: 'flex-end' }}>
            <Text style={{ color: Colors.black, fontWeight: '300' }}>{data?.qty ? data?.qty : data?.qtypesan}</Text>
          </View>
        </View>

        {(data?.order_total || data?.total_price) && <Text style={{ color: Colors.black, fontWeight: '300' }}>{"Total Harga : "} {<Text style={{ color: Colors.primaryColorHub, fontWeight: '400' }}>{data?.order_total ? data?.order_total : currency(data?.total_price, "")}</Text>}</Text>}

        {data?.sku_name && <Text style={{ color: Colors.black, fontWeight: '300' }}>{<Text style={{ color: Colors.primaryColorHub, fontWeight: '400' }}>{data?.sku_name}</Text>}</Text>}
      </View>

    </View>

  </View>
  
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default ItemOrder;