// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  Image,
  View,
  Text,
  FlatList
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import Buttons from '../../../Component/Button';
import TextInput from '../../../Component/TextInput';
import { Metrics, Scale } from '../../../utils/size';
import Account from './Account';
import { Routers } from '../../../utils/Routers';
import { getData, removeData } from '../../../utils/Storage';
import { Constants } from '../../../utils/Constans';
import { JSONAxioGet, JSONAxioDelete } from '../../../utils/services/JsonService';
import { getURL, deleteURL } from '../../../utils/services/API';
import { Eng } from '../../../utils/String';
import { Modal } from 'react-native';
import Loading from '../../../Component/loading';
import PopUp from '../../../Component/popUp';

const Profile = ({ route, navigation }) => {

  let [switchAccount, setswitchAccount] = useState(false);
  let [dataCoint, setDataCoint] = useState({ focoCoint: "0", focoPoint: "0", saldo: "0", totalReferal: 0 });
  let [loading, setLoading] = useState(false);
  let [modalLogOut, setModalLogOut] = useState(false);
  let [modalDeletedAccount, setModalDeletedAccount] = useState(false);
  let [loadingFull, setLoadingFull] = useState(false);
  let [contentWarning, setContentWarning] = useState(null);
  let [warning, setWarning] = useState(false);
  useEffect(() => {

    getDataCard()

  }, []);



  let [listItem, setlistItem] = useState([
    {
      title: 'Ubah Profile',
      flag: 'change_profile'
    },
    // {
    //   title: 'Ubah Email',
    //   flag: 'change_email'
    // },
    {
      title: 'Ubah Kata Sandi',
      flag: 'change_passsword'
    },
    {
      title: 'Kode Referal',
      flag: 'referal_code'
    },
    // {
    //   title: 'Team Saya',
    //   flag: 'my_team'
    // },
    // {
    //   title: 'Target Bonus Penjualan',
    //   flag: 'bonus_target'
    // },
    {
      title: 'Circle Saya',
      flag: 'my_referal'
    },
    {
      title: 'Reward Dan Komisi',
      flag: 'reward_comition'
    },
    // {
    //   title: 'History Pembelian',
    //   flag: 'history_payment'
    // },
    {
      title: 'Hapus Akun',
      flag: 'deleted_account'
    },
    {
      title: 'Log Out',
      flag: 'logout'
    }
  ]);

  const getDataCard = () => {
    getData(Constants.SESSION_HUB).then(res => {
      setswitchAccount(res ? true : false);
    });

    getData(Constants.SESSION_USER_PROFILE).then(res => {
      var params = {
        userid: res ? res.result.hp : '0'
      }
      if (res) {
        getPoint(params, res.result.token);
      }
    })
  }

  const onPressItem = (item) => {
    switch (item.flag) {
      // case 'change_profile': 
      // navigation.navigate(Routers.EDIT_PROFILE_SCREEN, {})
      // break;
      case 'change_email':
        navigation.navigate(Routers.EDIT_EMAIL_SCREEN, {})
        break;
      case 'change_passsword':
        navigation.navigate(Routers.EDIT_PASSWORD_SCREEN, { forgote: false })
        break;
      case 'my_team':
        navigation.navigate(Routers.MY_TEAM_SCREEN, {})
        break;
      case 'referal_code':
        navigation.navigate(Routers.KODE_REFERAL_SCREEN, {})
        break;
      case 'my_referal':
        navigation.navigate(Routers.MY_REFERAL_SCREEN, {})
        break;
      // case 'bonus_target': 
      // navigation.navigate(Routers.TARGET_BONUS_SCREEN, {})
      // break;
      case 'reward_comition':
        navigation.navigate(Routers.REWARDS_COMMISION_SCREEN, {})
        break;
      // case 'history_payment': 
      // navigation.navigate(Routers.HISTORY_SCREEN, {})
      // break;
      case 'deleted_account':
        setModalDeletedAccount(true)
        break;
      case 'logout':
        setModalLogOut(true)
        break;

    }

  }

  const logoutFunction = () => {
    setModalLogOut(false)
    removeData(Constants.SESSION_USER_PROFILE).then(() => {
      removeData(Constants.SESSION_HUB).then(() => {

        navigation.reset({ index: 0, routes: [{ name: Routers.MAIN_PAGE }] });
      });
    });
  }

  const getPoint = (params, token) => {
    setLoading(true);
    JSONAxioGet(getURL('get-coint', params), null, token)
      .then(respone => {
        const response = respone.data;
        setLoading(false);
        setDataCoint(response.result);
        if (response.statusCode == 1) {

        } else {

        }
      })
      .catch(error => {
        setLoading(false);
        console.log(error)
      });
  }

  const deletedAccount = (params, token) => {
    setLoadingFull(true);
    setModalDeletedAccount(false)
    getData(Constants.SESSION_USER_PROFILE).then(res => {
      JSONAxioDelete(deleteURL('delete-account', null), null, res.result.token)
        .then(respone => {
          setLoadingFull(false);
          const response = respone.data;
          console.log("response >>>>")
          console.log(response)
          if (response.statusCode == 1) {
            setModalDeletedAccount(false)
            cekError(1000, response.message);
            // logoutFunction()
          } else {
            setModalDeletedAccount(false)
            cekError(response.statusCode, response.message);
          }
        })
        .catch(error => {
          setLoadingFull(false);
          cekError(4, null);
          console.log("<<<<<<Deleted Error>>>>>>")
          console.log(error)
        });
    })
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "Login Kembali",
        statusCode: statusCode
      })
    }
    else if (statusCode == 1) {
      setContentWarning({
        title: "Yeey !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else if (statusCode == 1000) {
      setContentWarning({
        title: "Yeey !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setLoading(false);
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  const actionButton = () => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400 || contentWarning?.statusCode == 1000) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: "LoginStack" }] });
        });
      });
    }

  }

  return (
    <View style={{ flex: 1 }}>

      <Account
        onPresSwitch={() => console.log("")}
        dataCoint={dataCoint}
        switchAccount={switchAccount}
        navigation={navigation} />

      {/* <Buttons
        style={{ marginVertical: Scale(20), marginHorizontal : Scale(16)}}
        onPress={() => console.log("safasdas")}
        title={'Ubah Profile'} /> */}

      <FlatList
        style={{ marginTop: Scale(20) }}
        showsVerticalScrollIndicator={false}
        showsHorizontalScrollIndicator={false}
        refreshing={loading}
        data={listItem}
        onRefresh={() => { getDataCard() }}
        renderItem={({ item, index }) => (
          <TouchableOpacity
            onPress={() => onPressItem(item)}>

            <View style={{ flexDirection: 'row', borderColor: Colors.gray, borderWidth: Scale(1), borderRadius: Scale(8), marginHorizontal: Scale(16), marginVertical: Scale(8), padding: Scale(16) }}>
              <View style={{ flex: 1 }}>
                <Text style={[styles.text400]}>{item.title}</Text>
              </View>

              <View style={{ flex: 0.2, alignItems: 'flex-end' }}>
                <Image
                  style={{ height: Scale(12), width: Scale(12), tintColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }}
                  source={getIcon('ic_arrow_right')}
                  resizeMode='contain' />
              </View>
            </View>

          </TouchableOpacity>
        )
        }
      />

      <View style={{ height: Scale(40), justifyContent: 'center' }}>
        <Text style={{ textAlign: 'center', fontSize: Scale(10) }}>{Eng.VERSION_NAME}</Text>
      </View>


      <Modal
        style={{ backgroundColor: Colors.blackTrancparent, justifyContent: 'center', alignItems: 'center' }}
        animationType="slide"
        transparent={true}
        visible={modalLogOut}
        onRequestClose={() => { setModalLogOut(false) }}
      >

        <View style={{ height: Metrics.screenHeight, width: Metrics.screenWidth, backgroundColor: Colors.blackTrancparent }}>


          <View style={{
            flex: 1,
            marginTop: Metrics.screenHeight / 1.4,
            backgroundColor: Colors.white
          }}>

            <Text style={{ textAlign: 'center', marginTop: Scale(40) }}>Apakah anda ingin keluar dari aplikasi ini ?</Text>

            <View style={{ flexDirection: 'row', position: 'absolute', bottom: Scale(16) }}>

              <View style={{ flex: 1 }}>

                <Buttons
                  onPress={() => logoutFunction()}
                  style={{ height: Scale(50), margin: Scale(16), marginTop: Scale(10), borderRadius: Scale(8), backgroundColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }}
                  styleTitle={{ fontSize: Scale(12) }}
                  title={"Log Out"} />

              </View>

              <View style={{ flex: 1 }}>

                <Buttons
                  onPress={() => setModalLogOut(false)}
                  style={{ height: Scale(50), margin: Scale(16), marginTop: Scale(10), borderRadius: Scale(8), backgroundColor: Colors.red }}
                  styleTitle={{ fontSize: Scale(12) }}
                  title={"Tetap Login"} />

              </View>

            </View>



          </View>



        </View>
      </Modal>


      {/* DELETED ACCOUTNT */}
      <Modal
        style={{ backgroundColor: Colors.blackTrancparent, justifyContent: 'center', alignItems: 'center' }}
        animationType="slide"
        transparent={true}
        visible={modalDeletedAccount}
        onRequestClose={() => { setModalDeletedAccount(false) }}
      >

        <View style={{ height: Metrics.screenHeight, width: Metrics.screenWidth, backgroundColor: Colors.blackTrancparent }}>


          <View style={{
            flex: 1,
            marginTop: Metrics.screenHeight / 1.4,
            backgroundColor: Colors.white
          }}>

            <Text style={{ textAlign: 'center', marginTop: Scale(40) }}>Apakah anda ingin menghapus akun anda dari aplikasi ini ?</Text>

            <View style={{ flexDirection: 'row', position: 'absolute', bottom: Scale(16) }}>

              <View style={{ flex: 1 }}>

                <Buttons
                  onPress={() => deletedAccount()}
                  style={{ height: Scale(50), margin: Scale(16), marginTop: Scale(10), borderRadius: Scale(8), backgroundColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }}
                  styleTitle={{ fontSize: Scale(12) }}
                  title={"Hapus"} />

              </View>

              <View style={{ flex: 1 }}>

                <Buttons
                  onPress={() => setModalDeletedAccount(false)}
                  style={{ height: Scale(50), margin: Scale(16), marginTop: Scale(10), borderRadius: Scale(8), backgroundColor: Colors.red }}
                  styleTitle={{ fontSize: Scale(12) }}
                  title={"Tidak"} />

              </View>

            </View>



          </View>



        </View>
      </Modal>

      <Loading
        visible={loadingFull} />

      <PopUp
        visible={warning}
        onPressButton={() => { actionButton() }}
        title={contentWarning?.title}
        desc={contentWarning?.desc}
        titleButton={contentWarning?.titleButton} />

    </View>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  text400: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
});
export default Profile;