// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  FlatList,
  SafeAreaView,
  TextInput as TextInputRN,
  Image
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import Buttons from '../../../Component/Button';
import { Metrics, Scale } from '../../../utils/size';
import TextInput from '../../../Component/TextInput';
import { currency } from '../../../utils/General';

const ItemCard = ({ navigation, item, title, showCheckBox, onPresButton, checkBoxActive, onPresCheckBox, nopesanan, onpressDetil, onpresPlus, onpressMin, resultOnchange, status }) => {
  let [total, setTotal] = useState(item.qty_pesan);
  const [time, setTime] = useState(item?.timer ? item?.timer : 0);
  const onClikcDetil =()=>{

    item.qty_pesan = total;

    // onpressDetil(item)
  }

  const onClikcDetil2 =()=>{

    item.qty_pesan = total;

    onPresButton(item)
  }

  const onClikcPlus =()=>{
    setTotal(parseInt(total) + 1)

    item.qty_pesan = parseInt(total) + 1;
    onpresPlus(item)
  }

  const onClikcMinus =()=>{
    setTotal((total > 0 ? (parseInt(total) - 1) : total))
    item.qty_pesan = (total > 0 ? (parseInt(total) - 1) : total);
    onpressMin(item)
  }

  const onChanges =(total)=>{

    console.log(" >>> ", total)
    setTotal(parseInt(total ? total : 0))
    item.qty_pesan = parseInt(total ? total : 0)
    resultOnchange(item)
  }

  const decrement = () =>
  setTime((prevTime) => {
    return prevTime === 0 ? 0 : prevTime - 1;
  });

  useEffect(() => {
    const id = setInterval(decrement, 1000);
    return () => clearInterval(id);
  }, []);

  const format = (num) => {
    return num < 10 ? '0' + num : num.toString();
  };
  
  return (
    // <TouchableOpacity
    // onPress={() => {onClikcDetil()}}>

    <View style = {{marginVertical: Scale(4)}}>
      {nopesanan && <View style={{ flexDirection: 'row', backgroundColor: Colors.white, paddingBottom: Scale(4) }}>
        <View style={{ flex: 0.2 }}></View>
        <View style={{ flex: 1 }}>
          <Text style={[styles.text10, { alignItems: 'center', marginBottom: Scale(4), marginTop: Scale(10), marginLeft: Scale(-8) }]}>{'Nomor Transaksi'}</Text>
          <Text style={[styles.text40012, { color: Colors.black, marginLeft: Scale(-8) }]}>{item?.kode_transaksi}</Text>

          {<Text style={[styles.text10, { alignItems: 'center', marginBottom: Scale(4), marginTop: Scale(10), marginLeft: Scale(-8) }]}>{'Tanggal Pembelian'}</Text>}
          {item?.tanggal_beli && <Text style={[styles.text40012, { color: Colors.black, marginLeft: Scale(-8) }]}>{item?.tanggal_beli}</Text>}

          
        </View>
        <View style={{ flex: 1, alignItems: 'flex-end', justifyContent: 'center' }}>
        <Text style={[styles.text10, { alignItems: 'center', marginBottom: Scale(4), marginRight: Scale(8), marginTop: Scale(10) }]}>{'Status'}</Text>
        <Text style={[styles.text40012, { color: Colors.red, marginRight: Scale(8) }]}>{item?.status_proses}</Text>

        {item?.expBayar && <Text  style={[styles.text10, { alignItems: 'center', marginBottom: Scale(4), marginRight: Scale(8), marginTop: Scale(10) }]}>{'Batas Waktu Pembayaran'}</Text>}
        {item?.expBayar && <Text style={[styles.text40012, { color: Colors.red, marginRight: Scale(8) }]}>{item?.status_proses === 'Menunggu Pembayaran' ? (format(Math.floor(time / (3600 * 24))) + " : " + format(Math.floor((time / 3600) % 24)) + " : " + format(Math.floor((time / 60) % 60)) + " : " + format(time % 60)) : item?.expBayar}</Text>}
        </View>

      </View>}
      <View style={{ flexDirection: 'row', backgroundColor: Colors.white, paddingHorizontal: Scale(10), paddingVertical: Scale(10) }}>
        {showCheckBox && <View style={{ flex: 0.2 }}>
          <TouchableOpacity
            onPress={() => onPresCheckBox(checkBoxActive)}>
            <Image
              style={{ height: Scale(20), width: Scale(20) }}
              source={getIcon(checkBoxActive ? 'ic_checkbox' : 'ic_checkbox_blank')}
              resizeMode='contain' />
          </TouchableOpacity>
        </View>}

        <View style={{ flex: 0.6, marginLeft: Scale(8) }}>


          <Image
            style={{
              width: Scale(60),
              height: Scale(50),
              borderRadius: Scale(8)

            }}
            source={{
              uri: item?.url_gambar
            }}
            resizeMode="contain"
          />

          
        </View>

        <View style={{ flex: 1 }}>
          <Text style={[styles.text10, { alignItems: 'center', marginBottom: Scale(4) }]}>{'Nama Product'}</Text>
          <Text style={[styles.text60012, { alignItems: 'center', marginBottom: Scale(4) }]}>{item.nama_produk}</Text>
          <Text style={[styles.text10, { alignItems: 'center', marginBottom: Scale(4) }]}>{'Satuan'}</Text>
          <Text style={[styles.text300, { alignItems: 'center', marginBottom: Scale(4) }]}>{item?.teks_size ? item?.teks_size : "-"}</Text>

          {/* <Text style={[styles.text300, { alignItems: 'center', marginBottom: Scale(4) }]}>{'Total Pesanan : '}</Text> */}

          {showCheckBox &&
            <View style={{ marginTop: Scale(10), marginRight: Scale(18) }}>
              <Text style={[styles.text10, { alignItems: 'center', marginBottom: Scale(10) }]}>{'Ubah Jumlah'}</Text>
              <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                <View style={{ flex: 0.2 }}>

                  <Buttons
                    onPress={onClikcMinus}
                    style={{ width: Scale(25), height: Scale(25), margin: Scale(2), marginTop: Scale(0), borderRadius: Scale(4), backgroundColor: Colors.white, borderColor: Colors.primaryColor, borderWidth: Scale(1) }}
                    styleTitle={{ fontSize: Scale(16), color: Colors.primaryColor, textAlign: 'center' }}
                    title={"-"} />

                </View>

                <View style={{ flex: 0.5, alignItems: 'center', justifyContent: 'center', paddingLeft: Scale(10), paddingRight: Scale(2) }}>

                  <TextInputRN
                    style={{ flex: 1, height: Scale(14), color: Colors.black, justifyContent:'center', alignItems : 'center' }}
                    fontSize={Scale(14)}
                    textAlign='center'
                    onChangeText={(total) => onChanges(total)}
                    value={total.toString()}
                    keyboardType='numeric'
                  />
                </View>

                <View style={{ flex: 0.2, alignItems: 'flex-start' }}>

                  <Buttons
                    onPress={onClikcPlus}
                    style={{ width: Scale(25), height: Scale(25), margin: Scale(2), marginTop: Scale(0), borderRadius: Scale(4), backgroundColor: Colors.white, borderColor: Colors.primaryColor, borderWidth: Scale(1) }}
                    styleTitle={{ fontSize: Scale(16), color: Colors.primaryColor }}
                    title={"+"} />

                </View>
              </View>
            </View>}
        </View>

        <View style={{ flex: 0.7, alignItems: 'flex-end' }}>

          {!nopesanan && <Text style={[styles.text10, { alignItems: 'center', marginBottom: Scale(4) }]}>{'Status'}</Text>}
          {!nopesanan && <Text style={[styles.text300, { color: Colors.primaryColor, marginBottom: Scale(8) }]}>{'Belum Dibayar'}</Text>}
          <Text style={[styles.text10, { alignItems: 'center', marginBottom: Scale(4) }]}>{'Jumlah'}</Text>
          <Text style={[styles.text300, { alignItems: 'center', marginBottom: Scale(8) }]}>{total + ' pc'}</Text>
          <Text style={[styles.text10, { alignItems: 'center', marginBottom: Scale(4) }]}>{'Total Harga'}</Text>
          <Text style={[styles.text40012, { marginBottom: Scale(8), color: Colors.black }]}>{nopesanan ? item.total_price : ('Rp. ' + currency(item.retail_price * total))}</Text>

          
        </View>



      </View>

      <Buttons
            onPress={() => {onClikcDetil2()}}
            style={{ height: Scale(30), margin: Scale(2), marginTop: Scale(0), borderRadius: Scale(4) }}
            styleTitle={{ fontSize: Scale(12) }}
            title={title ? title : "Ubah"} />

    </View>

    // </TouchableOpacity>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
    
  },
  text10: { color: Colors.primaryColor, fontSize: Scale(8) },
  text300: { color: Colors.black, fontWeight: '300', fontSize: Scale(10) },
  text40012: { color: Colors.black, fontWeight: '400', fontSize: Scale(12) },
  text60012: { color: Colors.black, fontWeight: '600', fontSize: Scale(10) },

});
export default ItemCard;