// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useState }  from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  Image,
  View,
  Text,
  SafeAreaView
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import { Scale } from '../../../utils/size';

const TabLogin = ({ onPressTab, activeLogins, activeRegisters }) => {
  let [activeLogin, setActiveLogin] = useState(true);
  let [activeRegister, setActiveRegister] = useState(false);

  const onPressTabs =(param)=>{
    setActiveLogin((param == 'login' ? true :false));
    setActiveRegister((param == 'register' ? true :false));

    onPressTab(param == 'login' ? true :false)
  }

  return (
      <View style={{padding: 16, backgroundColor: Colors.greenWhite }}>

        <View style={{ flexDirection: 'row', marginTop : Scale(18) }}>

          <Text
            style={{
              fontSize: Scale(16),
              color: Colors.black,
              fontWeight: '600'
            }}>
            {(activeLogin || activeLogins) ? "Masuk " : 'Daftar '}
          </Text>

          <Image
            style={{ height: Scale(20), width: Scale(20), marginHorizontal: Scale(8) }}
            source={getIcon('ic_user_line')} 
            resizeMode='contain'/>

        </View>

        <Text
            style={{
              fontSize: Scale(16),
              color: Colors.black,
              fontWeight: '200'
            }}>
            {"Hello , welcome back to our account !"}
          </Text>

          <View style={{height : Scale(0.5), backgroundColor: Colors.line, marginVertical: Scale(18)}}/>


          <View style ={{backgroundColor : Colors.gray, height: Scale(50), marginHorizontal : Scale(40), borderRadius: Scale(20), justifyContent:'center'}}>
            
            <View style ={{flexDirection : 'row'}}>

            <TouchableOpacity
            style={{ flex: 1, height: Scale(35), backgroundColor: ((activeLogins)  ? Colors.primaryColor : Colors.gray), borderRadius: Scale(20), marginLeft: Scale(6), justifyContent: 'center', alignItems: 'center' }}
            onPress={() => onPressTabs ('login')}>
              <View >
                <Text
                  style={{
                    fontSize: Scale(16),
                    color: (( activeLogins)  ? Colors.white : Colors.txtGray),
                    fontWeight: '600'
                  }}>
                  {"Masuk"}
                </Text>
              </View>
            </TouchableOpacity>

            <TouchableOpacity
            style={{ flex: 1, height: Scale(35), backgroundColor: (!activeLogins ? Colors.primaryColor : Colors.gray), borderRadius: Scale(20), marginRight: Scale(6), justifyContent: 'center', alignItems: 'center' }}
            onPress={() => onPressTabs('register')}>
              <View >
                <Text
                  style={{
                    fontSize: Scale(16),
                    color: (!activeLogins ? Colors.white : Colors.txtGray),
                    fontWeight: '500'
                  }}>
                  {"Daftar"}
                </Text>
              </View>
            </TouchableOpacity>

            </View>

          </View>
        
      </View>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default TabLogin;