// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, {useEffect, useState }  from 'react';

// import { Icon } from "react-native-vector-icons/MaterialIcons";
import
FontAwesome
from 'react-native-vector-icons/FontAwesome5';

import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { Colors } from '../../Assets/Colors';
import HomeScreen from '../HomeScreen';
import MyCartScreen from '../MyCartScreen';
import DetilCart from '../MyCartScreen/DetilCart';
import DetailsScreen from '../DetailsScreen';
import ProfileScreen from '../ProfileScreen';
import SettingsScreen from '../SettingsScreen';
import { Routers } from '../../utils/Routers';
import ConfirmationOrderScreen from '../ConfirmationOrderScreen';
import MethodeSendScreen from '../MethodeSendScreen';
import PaymentMethodeScreen from '../PaymentMethodeScreen';
import VoucherScreen from '../VoucherScreen';
import SuccessScreen from '../SuccessScreen';
import PeymentGatewayScreen from '../PeymentGatewayScreen';
import SearchAddressScreen from '../SearchAddressScreen';
import EditProfileScreen from '../ProfileScreen/EditProfile';
import EditEmail from '../ProfileScreen/EditEmail';
import EditPassword from '../ProfileScreen/EditPassword';
import MyTeam from '../ProfileScreen/MyTeam';
import Addrerss from '../SearchAddressScreen/AddAddrerss';
import KodeReferal from '../ProfileScreen/KodeReferal';
import TargetBonus from '../ProfileScreen/TargetBonus';
import TargetBonusDetil from '../ProfileScreen/TargetBonus/TargetBonusDetil';
import RewardsComision from '../ProfileScreen/RewardsComision';
import RewardsComisionDetil from '../ProfileScreen/RewardsComision/RewardsComisionDetil';
import Pencairan from '../ProfileScreen/Pencairan';
import History from '../ProfileScreen/History';
import CameraScanQR from '../CameraScanQR';
import { Constants } from '../../utils/Constans';
import { getData } from '../../utils/Storage';
import AllNewOrder from '../HomeScreen/HubScreen/AllNewOrder';
import DetilOrderHubScreen from '../HomeScreen/HubScreen/DetilOrderHubScreen';
import ProvinceScreen from '../SearchAddressScreen/Province';
import TakeOrder from '../HomeScreen/HubScreen/TakeOrder';
import DetilDokumenSerahTerimaScreen from '../HomeScreen/HubScreen/DetilDokumenSerahTerimaScreen';
import DetilPengirimanScreen from '../HomeScreen/HubScreen/DetilPengirimanScreen';
import Comitsion from '../Comitsion';
import DetilComitionScreen from '../Comitsion/DetilOrderHubScreen';
import OtpScreen from '../ProfileScreen/OtpScreen';
import HistoryPencairan from '../ProfileScreen/HistoryPencairan';
import Cod from '../ProfileScreen/Cod';
import RiwayatCod from '../ProfileScreen/RiwayatCod';
import ComistionHub from '../ComistionHub';
import CodCoHub from '../ProfileScreen/CodHub';
import MyReferal from '../ProfileScreen/MyReferal';
import ForgotePassword from '../ProfileScreen/ForgotePassword';

const Stack = createNativeStackNavigator();
const Tab = createBottomTabNavigator();

const MainApp = () => {

  let [switchAccount, setswitchAccount] = useState(false);


  useEffect(() => {
    getData(Constants.SESSION_HUB).then(res => {
      setswitchAccount(res ? true :  false);
    });
    
  }, []);
  return (

  <Tab.Navigator
        initialRouteName="Feed"
        screenOptions={({ route }) => ({
          tabBarActiveTintColor: 'tomato',
          tabBarInactiveTintColor: 'gray',
          tabBarIconStyle:{
              marginTop:4
            },
            tabBarLabelStyle:{
              marginBottom:4
            },
            headerShown:false,
          tabBarIcon: ({ focused, color, size }) => {
            let iconName;

            if (route.name === 'HomeStack') {
              iconName =  focused
                ? 'home'
                : 'home';
            }
            else if (route.name === 'CategorysStack') {
              iconName = focused
                ? 'th-large'
                : 'th-large';
            }
            else if (route.name === 'MyCartStack') {
              iconName = focused
                ? 'shopping-cart'
                : 'shopping-cart';
            }
            else if (route.name === 'LoginStack') {
              iconName = focused
                ? 'user-friends'
                : 'user-friends';
            }

            
            return (
              <FontAwesome
                name={iconName}
                size={20}
                color={color}
              />
            );
          }
        })}>
        <Tab.Screen
          name="HomeStack"
          component={HomeStack}
          options={{
            tabBarLabel: 'Home',
            title: 'Home',
            tabBarActiveTintColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor,
            
          }}  />
        <Tab.Screen
          name="CategorysStack"
          component={CategorysStack}
          options={{
            tabBarLabel: 'Katagori',
            title: 'Katagori',
            tabBarActiveTintColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor
          }} />
           <Tab.Screen
          name="MyCartStack"
          component={MyCartStack}
          options={{
            tabBarLabel: switchAccount ? 'Pesanan' : 'Keranjang',
            title: switchAccount ? 'Pesanan' : 'Keranjang',
            tabBarActiveTintColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor
          }} />


        <Tab.Screen
          name="LoginStack"
          component={LoginStack}
          options={{
            tabBarLabel: 'Akun',
            title: 'Akun',
            tabBarActiveTintColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor
          }} />

      </Tab.Navigator>
  )
}

function HomeStack() {
  return (
      <Stack.Navigator
        initialRouteName="Home"
        screenOptions={{headerShown: false}}
        >
        <Stack.Screen
          name="Home"
          component={HomeScreen} />
        {/* <Stack.Screen
          name="Details"
          component={DetailsScreen} /> */}
      </Stack.Navigator>
  );
}

function CategorysStack() {
  return (
    <Stack.Navigator
      initialRouteName="Settings"
      screenOptions={{headerShown: false}}>
      <Stack.Screen
        name="Settings"
        component={SettingsScreen} />
      {/* <Stack.Screen
        name="Profile"
        component={ProfileScreen} /> */}
    </Stack.Navigator>
  );
}

function MyCartStack() {
  return (
    <Stack.Navigator
      initialRouteName="MyCartScreen"
      screenOptions={{headerShown: false}}>
      <Stack.Screen
        name="MyCartScreen"
        component={MyCartScreen} />
      {/* <Stack.Screen
        name="Profile"
        component={ProfileScreen} /> */}
    </Stack.Navigator>
  );
}

function LoginStack() {
  return (
    <Stack.Navigator
      initialRouteName="Profile"
      screenOptions={{headerShown: false}}>
      <Stack.Screen
        name="Profile"
        component={ProfileScreen} />
      {/* <Stack.Screen
        name="Profile"
        component={ProfileScreen} /> */}
    </Stack.Navigator>
  );
}


const Router = () => {
  return (
    <Stack.Navigator
      screenOptions={{
        lazy: false,
        headerShown: false,
      }}>

      <Stack.Screen
        name={Routers.MAIN_PAGE}
        component={MainApp}
      />

      <Stack.Screen
        name={Routers.CONFIRMATION_ORDER_PAGE}
        component={ConfirmationOrderScreen}
      />

      <Stack.Screen
        name={Routers.METODE_SEND}
        component={MethodeSendScreen}
      />

      <Stack.Screen
        name={Routers.PAYMENT_METODE}
        component={PaymentMethodeScreen}
      />

      <Stack.Screen
        name={Routers.VOUCHER_SCREEN}
        component={VoucherScreen}
      />

      <Stack.Screen
        name={Routers.SUCCESS_SCREEN}
        component={SuccessScreen}
      />

      <Stack.Screen
        name={Routers.PAYMENT_GATEWAY_SCREEN}
        component={PeymentGatewayScreen}
      />


      <Stack.Screen
        name={Routers.SEARCH_ADDRESS_SCREEN}
        component={SearchAddressScreen}
      />

      <Stack.Screen
        name={Routers.DETIL_PENGIRIMAN_SCREEN}
        component={DetilPengirimanScreen}
      />


      <Stack.Screen
        name={Routers.EDIT_PROFILE_SCREEN}
        component={EditProfileScreen}
      />

      <Stack.Screen
        name={Routers.EDIT_EMAIL_SCREEN}
        component={EditEmail}
      />
      <Stack.Screen
        name={Routers.EDIT_PASSWORD_SCREEN}
        component={EditPassword}
      />

      <Stack.Screen
        name={Routers.FORGOTE_PASSWORD_SCREEN}
        component={ForgotePassword}
      />

      <Stack.Screen
        name={Routers.MY_TEAM_SCREEN}
        component={MyTeam}
      />

      <Stack.Screen
        name={Routers.MY_REFERAL_SCREEN}
        component={MyReferal}
      />

      <Stack.Screen
        name={Routers.ADDRESS_SCREEN}
        component={Addrerss}
      />
      <Stack.Screen
        name={Routers.KODE_REFERAL_SCREEN}
        component={KodeReferal}
      />
      <Stack.Screen
        name={Routers.TARGET_BONUS_SCREEN}
        component={TargetBonus}
      />
      <Stack.Screen
        name={Routers.TARGET_BONUS_DETIL_SCREEN}
        component={TargetBonusDetil}
      />
       <Stack.Screen
        name={Routers.REWARDS_COMMISION_SCREEN}
        component={RewardsComision}
      />

      <Stack.Screen
        name={Routers.PENCAIRAN_SCREEN}
        component={Pencairan}
      />

      <Stack.Screen
        name={Routers.COD_SCREEN}
        component={Cod}
      />

      <Stack.Screen
        name={Routers.RIWAYAT_COD_SCREEN}
        component={RiwayatCod}
      />


      <Stack.Screen
        name={Routers.HISTORY_PENCAIRAN_SCREEN}
        component={HistoryPencairan}
      />

      
      <Stack.Screen
        name={Routers.REWARDS_COMMISION_DETIL_SCREEN}
        component={RewardsComisionDetil}
      />
      <Stack.Screen
        name={Routers.HISTORY_SCREEN}
        component={History}
      />
       <Stack.Screen
        name={Routers.CAMERA_SCAN_QR_SCREEN}
        component={CameraScanQR}
      />
       <Stack.Screen
        name={Routers.TAKE_ORDER_SCREEN}
        component={TakeOrder}
      />
       <Stack.Screen
        name={Routers.ALL_NEW_ORDER_SCREEN}
        component={AllNewOrder}
      />

      <Stack.Screen
        name={Routers.COMITION}
        component={Comitsion}
      />

      <Stack.Screen
        name={Routers.DETIL_COMITION_SCREEN}
        component={DetilComitionScreen}
      />

      <Stack.Screen
        name={Routers.COMITSION_COHUB_SCREEN}
        component={ComistionHub}
      />

      <Stack.Screen
        name={Routers.OTP_SCREEN}
        component={OtpScreen}
      />
      
      <Stack.Screen
        name={Routers.COD_CO_HUB}
        component={CodCoHub}
      />

      

      <Stack.Screen
        name={Routers.DETIL_ORDER_HUB_SCREEN}
        component={DetilComitionScreen}
      />


      <Stack.Screen
        name={Routers.DETIL_DOKUMEN_SERAH_TERIMA_SCREEN}
        component={DetilDokumenSerahTerimaScreen}
      />

      <Stack.Screen
        name={Routers.PROVINCE_SCREEN}
        component={ProvinceScreen}
      />

<Stack.Screen
        name={Routers.DETIL_CART}
        component={DetilCart}
      />



    </Stack.Navigator>
  )
}
function TabBottom() {
  return (
    <NavigationContainer>
      <Router/>
    </NavigationContainer>
  );
}
export default TabBottom;