import React, {useEffect} from 'react';
import notifee, {AndroidImportance} from '@notifee/react-native';
import messaging from '@react-native-firebase/messaging';
import {storeData} from '../Storage';
import { Constants } from '../Constans';
import { PermissionsAndroid } from 'react-native';

const Notifee = () => {
  useEffect(() => {
    requestPermission();

    messaging().setBackgroundMessageHandler(async remoteMessage => {
      console.log('Message handled in the background!', remoteMessage);
         });

    const unsubscribe = messaging().onMessage(async remoteStatus => {
      DisplayNotification(remoteStatus);
    });
    return unsubscribe;


  }, []);

  const requestPermission = async () => {
    const authResponse = await messaging().requestPermission();
    // const enabled =
    //   authResponse === PermissionsAndroid.PERMISSIONS.POST_NOTIFICATIONS
    // if (enabled) {
    //   const fcmToken = await messaging().getToken();
    //   console.log('token fcmsss =>>>', fcmToken);
    //   storeData(Constants.FCM_TOKEN, {value: fcmToken});
    // }

    try {
      PermissionsAndroid.check('android.permission.POST_NOTIFICATIONS').then(
        async response => {
          if(!response){
            PermissionsAndroid.request('android.permission.POST_NOTIFICATIONS',{
                title: 'Ijin Notifikasi',
                message:
                  'Menerima notifikasi akan memastikan Anda tidak ketinggalan informasi terbaru dari kami. Boleh kami kirimkan pemberitahuan?',
                buttonNeutral: 'Ask Me Later',
                buttonNegative: 'Cancel',
                buttonPositive: 'OK',
            })
          } else {
            const fcmToken = await messaging().getToken();
            console.log('token fcmsss =>>>', fcmToken);
            storeData(Constants.FCM_TOKEN, { value: fcmToken });
          }
        })}catch (err){
          console.log(err);
        }
  };



  async function DisplayNotification(remoteMessage) {
    const {notification, data} = remoteMessage;
    const channelId = await notifee.createChannel({
      id: Constants.NTFX_CHANNEL_ID,
      name: Constants.NTFX_CHANNEL_NAME,
      vibration: true,
      importance: AndroidImportance.HIGH,
    });

   

    await notifee.displayNotification({
      title: notification.title,
      body: notification.body,
      data: data,
      android: {
        channelId,
        smallIcon: 'ic_launcher', // optional, defaults to 'ic_launcher'.
      },
    });
  }
};

export default Notifee;
