// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  StyleSheet,
  View,
  Text,
  Image,
  FlatList,
  TouchableOpacity
} from 'react-native';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import { Metrics, Scale } from '../../../utils/size';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import ItemOrder from './ItemOrder';
import { Routers } from '../../../utils/Routers';
import ModalConformationSendHub from '../../../Component/ModalConformationSendHub';
import { getData, removeData } from '../../../utils/Storage';
import { Constants } from '../../../utils/Constans';
import { JSONAxioGet, JSONAxioGetNew, JSONAxioPost } from '../../../utils/services/JsonService';
import { getURLHub, postURL } from '../../../utils/services/API';
import Loading from '../../../Component/loading';
import PopUp from '../../../Component/popUp';
import ItemOrderCoHub from './ItemOrderCoHub';

const HubScreen = ({ navigation, newsOrder, token, searchActive }) => {

  const [showModalConfirm, setShowModalConfirm] = useState(false);
  const [selectItem, setSelectItem] = useState(null);
  const [titleNewOrder, setTitleNewOrder] = useState("Pesanan Baru");
  const [descNewOrder, setDescNewOrder] = useState("Anda Mendapatkan Pesanan Baru, Kelola Sekarang");
  let [menu, setMenu] = useState([
    { name: 'Pengiriman', icon: 'ic_new_order', flag: 'new_order' },
    { name: 'Ambil Kiriman', icon: 'ic_new_send', flag: 'new_send' },
    { name: 'Order Retur', icon: 'ic_retur_order', flag: 'retur_order' },
    { name: 'Finance', icon: 'ic_finance', flag: 'finance' },
    { name: 'Inventory', icon: 'ic_inventory', flag: 'inventory' },
    { name: 'Logistik', icon: 'ic_logistic', flag: 'logistic' },
  ]);
  let [loading, setLoading] = useState(false);
  let [hub, setHub] = useState(true);
  let [userRole, setUserRole] = useState(null);
  const [dataDetil, setDataDetil] = useState(null);
  let [contentWarning, setContentWarning] = useState(null);
  let [warning, setWarning] = useState(false);

  useEffect(() => {
    getData(Constants.SESSION_HUB).then(res => {
      if (res) {

        setUserRole(JSON.parse(res).userRole);

        if (JSON.parse(res).userRole === "HUB") {
          setHub(true)
          setTitleNewOrder("Daftar Pengiriman")
          setDescNewOrder("Daftar Pengiriman Anda, Kelola Sekarang")
          setMenu([
            { name: 'Pengiriman', icon: 'ic_new_order', flag: 'new_order' },
            { name: 'Ambil Kiriman', icon: 'ic_new_send', flag: 'new_send' },
            { name: 'Order Retur', icon: 'ic_retur_order', flag: 'retur_order' },
            { name: 'Finance', icon: 'ic_finance', flag: 'finance' },
            { name: 'Inventory', icon: 'ic_inventory', flag: 'inventory' },
            { name: 'Logistik', icon: 'ic_logistic', flag: 'logistic' },
          ])

        } else if (JSON.parse(res).userRole === "COHUB") {
          setTitleNewOrder("Kiriman Pabrik")
          setDescNewOrder("Daftar Pengiriman Pabrik Kelokasi Anda, Kelola Sekarang")
          setHub(false)

          setMenu([
            { name: 'Kiriman Pabrik', icon: 'ic_new_order', flag: 'new_order' },
            { name: 'Pengambilan HUB', icon: 'ic_new_send', flag: 'new_send' },
            { name: 'Order Retur', icon: 'ic_retur_order', flag: 'retur_order' },
            { name: 'Finance', icon: 'ic_finance', flag: 'finance' },
            { name: 'Inventory', icon: 'ic_inventory', flag: 'inventory' },
            { name: 'Logistik', icon: 'ic_logistic', flag: 'logistic' },
          ])
        }

      } else {
        setMenu([
          { name: 'Pengiriman', icon: 'ic_new_order', flag: 'new_order' },
          { name: 'Ambil Kiriman', icon: 'ic_new_send', flag: 'new_send' },
          { name: 'Order Retur', icon: 'ic_retur_order', flag: 'retur_order' },
          { name: 'Finance', icon: 'ic_finance', flag: 'finance' },
          { name: 'Inventory', icon: 'ic_inventory', flag: 'inventory' },
          { name: 'Logistik', icon: 'ic_logistic', flag: 'logistic' },
        ])
      }
    })
  }, []);

  const selectedItem = (item) => {
    var params = {
      "transaction_id": item.transaction_id
    }
    getDetilProductHubCoHub(params, token, "modal")
  }

  const selectedMenu = (item) => {
    if (hub) {
      switch (item.flag) {
        case 'new_order':
          navigation.navigate((hub ? Routers.ALL_NEW_ORDER_SCREEN : Routers.TAKE_ORDER_SCREEN), { title: "Kiriman Pabrik", filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terkirim', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: false, search: true })
          break;
        case 'new_send':
          navigation.navigate(Routers.TAKE_ORDER_SCREEN, { title: "Detail Dokumen Serah Terima", filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terima', qrCode: false, showPhone: false, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: true, search: true  })
          break;
          case 'finance':
            navigation.navigate(Routers.REWARDS_COMMISION_SCREEN, {});
            break;
      }
    } else {
      switch (item.flag) {
        case 'new_order':
          navigation.navigate((Routers.TAKE_ORDER_SCREEN), { title: "Kiriman Pabrik", filter: { name: 'Daftar Baru', flag: 'all', status: true, id: 0 }, buttonName: 'Terima', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: true, isDataPengambilanHub: false, urlTakeOreder: 'api_cohub_terima_dst', isHubSend: false, isHubGet: false, search: true })
          break;
        case 'new_send':
          navigation.navigate(Routers.TAKE_ORDER_SCREEN, { title: "Dokumen Serah Terima", filter: { name: 'Siap Diserahkan', flag: 'all', status: true, id: 1 }, buttonName: 'Konfirmasi Penyerahan', qrCode: true, showPhone: false, showOtherButton: true, url: "api-cohub-list-dst-diterima", urlTakeOreder: 'api_cohub_serahkan_dst', isDataCohubPabrik: false, isDataPengambilanHub: true, isHubSend: false, isHubGet: false, search: true })
          break;
        case 'finance':
          navigation.navigate(Routers.REWARDS_COMMISION_SCREEN, {});
          break;
         
      }
    }

  }

  const onPresHubSendConfirm = (value) => {
    setShowModalConfirm(!showModalConfirm)
    if (value) {
      navigation.navigate(Routers.SUCCESS_SCREEN, { title: 'Pengiriman Diproses', desc: 'Terimakasih , Pengiriman produk kamu telah berhasil dan sedang di proses , Klik tombol dibawah untuk cek status pengiriman kamu', titleButton: 'Kirim Pesanan Lainnya' })
    }
  }

  const onPresHDetil = (item) => {
    var params = {
      "transaction_id": item.transaction_id
    }
    getDetilProductHubCoHub(params, token, "page", item)
  }

  const getDetilProductHubCoHub = (params, token, page, item) => {
    setLoading(true);
    JSONAxioGetNew(getURLHub('get-detil-product-hub', params), null, token)
      .then(respone => {
        setLoading(false);
        const response = respone.data;

        if (response.statusCode == 1) {

          var isArray = Array.isArray(response.result);
          var results = null;
          if (isArray) {
            results = response.result[0];
          } else {
            results = response.result;
          }
          setDataDetil(results)

          if (page === 'modal') {
            setShowModalConfirm(!showModalConfirm)
          } else {
            navigation.navigate(Routers.DETIL_ORDER_HUB_SCREEN, { data: results, item: item })
          }


        } else {

          cekError(response.statusCode, response.message);

        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "Login Kembali",
        statusCode: statusCode
      })
    } else if (statusCode == 1) {
      setContentWarning({
        title: "Yeyy !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  const actionButton = (statusCode) => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: Routers.MAIN_PAGE }] });
        });
      });
    }

  }

  const actionTerimaCohub = (item) => {


    var param = {
      "no_dst": item.no_dst
    }

    setLoading(true);

    getData(Constants.SESSION_USER_PROFILE).then(res => {
      JSONAxioPost(postURL('api_cohub_terima_dst', null), param, res.result.token)
        .then(respone => {
          const response = respone?.data;
          setLoading(false);
          if (response?.statusCode == 1) {
            navigation.navigate(Routers.SUCCESS_SCREEN, { title: 'Berhasil Diterima', desc: 'Dokumen Serah Terima Berhasil Anda Terima Silakan Lanjutkan Proses Pengiriman', titleButton: 'Pesanan Siap Kirim' });
          } else {
            cekError(response.statusCode, response.message);
          }
        })
        .catch(error => {
          setLoading(false);
          cekError(2, null);

        });

    });
  }

  const onPresDetilCOHUB = (item) => {
    navigation.navigate(Routers.DETIL_DOKUMEN_SERAH_TERIMA_SCREEN, { data: item, title: "Kiriman Pabrik", filter: { name: 'Daftar Baru', flag: 'all', status: true, id: 0 }, titleButtonDetil: 'Terima', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: true, isDataPengambilanHub: false })
  }

  return (
    <View style={styles.container}>

      {!searchActive && <View
        key={0}
        style={{
          padding: Scale(8),
          height: Scale(170),
          marginHorizontal: Scale(16),
          marginVertical: Scale(16),
          borderTopColor: Colors.primaryColorHub,
          borderBottomColor: Colors.primaryColorHub,
          borderTopWidth: Scale(1),
          borderBottomWidth: Scale(1)
        }}>
        <FlatList
          showsVerticalScrollIndicator={false}
          showsHorizontalScrollIndicator={false}
          numColumns={3}
          horizontal={false}
          data={menu}
          renderItem={({ item, index }) =>
          (
            <TouchableOpacity
              onPress={() => selectedMenu(item)}>
              <View style={{ marginHorizontal: Scale(4), marginVertical: Scale(8), width: Metrics.screenWidth / 3.8, alignItems: 'center', }}>
                <Image
                  style={{ height: Scale(40), width: Scale(40) }}
                  source={getIcon(item.icon)}
                  resizeMode='contain' />

                <Text style={[styles.text40012, { textAlign: 'center' }]}>{item.name}</Text>
              </View>
            </TouchableOpacity>
          )} />
      </View>}

      {!searchActive && <View style={{ paddingHorizontal: Scale(16) }}>
        {(newsOrder.length > 0) && <View style={{ flexDirection: 'row' }}>
          <View style={{ flex: 1 }}>
            <Text style={[styles.text600]}>{titleNewOrder}</Text>
          </View>
          <TouchableOpacity
            onPress={() => selectedMenu(menu[0])}>
            <View style={{ flex: 1, alignItems: 'flex-end' }}>
              <Text style={[styles.text60012]}>{"Lihat Selengkapnya"}</Text>

            </View>
          </TouchableOpacity>
        </View>}

        {(newsOrder.length > 0) && <Text style={[styles.text40012, { marginVertical: Scale(8) }]}>{descNewOrder}</Text>}

      </View>}

      {userRole === "HUB" && (newsOrder.length > 0) && newsOrder.map((item, i) =>
      (<ItemOrder
        key={i}
        onPressSend={() => selectedItem(item)}
        navigation={navigation}
        onPress={() => onPresHDetil(item)}
        data={item} />)
      )}

      {userRole === "COHUB" && (newsOrder.length > 0) && newsOrder.map((item, i) =>
      (<ItemOrderCoHub
        search={true}
        navigation={navigation}
        key={i}
        onPressSend={() => actionTerimaCohub(item)}
        onPress={() => onPresDetilCOHUB(item)}
        data={item} />)
      )}

      {(newsOrder.length == 0) && <View style={{ height: Metrics.screenHeight / 1.5, justifyContent: 'center', alignItems: 'center', padding: Scale(16) }}>

      <Image
          style={{ height: Scale(150), width: Scale(150) }}
          source={getIcon('img_oops')}
          resizeMode='contain' />

        <Text style={{ fontSize: Scale(18), textAlign: 'center' }}>Anda belum Mendapatkan Pesanan Baru saat ini</Text>


      </View>}

      <ModalConformationSendHub
        data={dataDetil}
        onPresButtonConfirm={(value) => onPresHubSendConfirm(value)}
        onCloses={() => setShowModalConfirm(false)}
        ShowComment={showModalConfirm}
        loading={(value) => setLoading(value)}
        cekError={(value1, value2) => cekError(value1, value2)}
      />

      <Loading
        visible={loading} />

      <PopUp
        visible={warning}
        onPressButton={() => { actionButton() }}
        title={contentWarning?.title}
        desc={contentWarning?.desc}
        titleButton={contentWarning?.titleButton} />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  containerRow: { flexDirection: 'row' },
  imgRow: { height: Scale(40), width: Scale(40) },
  viewCenter: { flex: 1, justifyContent: 'center' },
  viewCenterPadding: { paddingLeft: Scale(16), paddingRight: Scale(16) },
  text600: { color: Colors.black, fontWeight: '600', fontSize: Scale(14) },
  text60012: { color: Colors.black, fontWeight: '600', fontSize: Scale(12) },
  text40012: { color: Colors.black, fontWeight: '400', fontSize: Scale(12) },
  text40014: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
  viewRowSaldo: { flexDirection: 'row', height: Scale(60), backgroundColor: Colors.gray, marginVertical: Scale(8), borderRadius: Scale(10), padding: Scale(10) }

});
export default HubScreen;