// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, {useEffect,  useState }  from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  Image,
  View,
  Text,
  FlatList
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import Buttons from '../../../Component/Button';
import TextInput from '../../../Component/TextInput';
import { Metrics, Scale } from '../../../utils/size';
import Account from '../Profile/Account';
import { Routers } from '../../../utils/Routers';
import Toolbar from '../../../Component/Toolbar';
import { getData, removeData } from '../../../utils/Storage';
import { Constants } from '../../../utils/Constans';
import { JSONAxioGet } from '../../../utils/services/JsonService';
import { getURL } from '../../../utils/services/API';
import PopUp from '../../../Component/popUp';

const RewardsComision = ({ route, navigation }) => {

  let [switchAccount, setswitchAccount] = useState(false);
  let [hub, setHub] = useState(null);
  let [dataCoint, setDataCoint] = useState({ focoCoint: "0", focoPoint: "0", saldo: "0", totalReferal: 0 });
  let [loading, setLoading] = useState(false);
  let [contentWarning, setContentWarning] = useState(null);
  let [warning, setWarning] = useState(false);
  let [listItem, setlistItem] = useState([
    {
      title: 'Poin',
      target: 'Rp,15.500.000',
      icon: 'ic_share_coint',
      flag: 'foco_point'
    },
    {
      title: 'Coin',
      target: 'Rp,17.500.000',
      icon: 'ic_coint',
      flag: 'foco_coint'

    },
    {
      title: 'Komisi Saya',
      target: 'Rp,17.500.000',
      icon: 'ic_box',
      flag: 'comition_send'
    }
  ]);

  useEffect(() => {
    getData(Constants.SESSION_HUB).then(res => {
      
      setswitchAccount(res ? true :  false);

      if (res) {
        setHub(JSON.parse(res).userRole)
        if (JSON.parse(res).userRole === "COHUB") {

          setlistItem([
            {
              title: 'Poin',
              target: 'Rp,15.500.000',
              icon: 'ic_share_coint',
              flag: 'foco_point'
            },
            {
              title: 'Coin',
              target: 'Rp,17.500.000',
              icon: 'ic_coint',
              flag: 'foco_coint'

            },
            {
              title: 'Komisi Saya',
              target: 'Rp,17.500.000',
              icon: 'ic_box',
              flag: 'comition_send'
            },
            {
              title: 'Setoran COD',
              target: 'Rp,17.500.000',
              icon: 'ic_cod_s',
              flag: 'cod'
            },
            // {
            //   title: 'Riwayat Setoran COD',
            //   target: 'Rp,17.500.000',
            //   icon: 'ic_cod_s',
            //   flag: 'riwayat_cod'
            // },
            {
              title: 'Pencairan',
              target: 'Rp,17.500.000',
              icon: 'ic_history_pencairan',
              flag: 'pencairan'
            },
            {
              title: 'History Pencairan',
              target: 'Rp,17.500.000',
              icon: 'ic_pencairan',
              flag: 'history_pencairan'
            }
          ])

        } else {
          setlistItem([
            {
              title: 'Poin',
              target: 'Rp,15.500.000',
              icon: 'ic_share_coint',
              flag: 'foco_point'
            },
            {
              title: 'Coin',
              target: 'Rp,17.500.000',
              icon: 'ic_coint',
              flag: 'foco_coint'

            },
            {
              title: 'Komisi Saya',
              target: 'Rp,17.500.000',
              icon: 'ic_box',
              flag: 'comition_send'
            },
            {
              title: 'Setoran COD',
              target: 'Rp,17.500.000',
              icon: 'ic_cod_s',
              flag: 'cod'
            },
            {
              title: 'Riwayat Setoran COD',
              target: 'Rp,17.500.000',
              icon: 'ic_cod_s',
              flag: 'riwayat_cod'
            },
            {
              title: 'Pencairan',
              target: 'Rp,17.500.000',
              icon: 'ic_history_pencairan',
              flag: 'pencairan'
            },
            {
              title: 'History Pencairan',
              target: 'Rp,17.500.000',
              icon: 'ic_pencairan',
              flag: 'history_pencairan'
            }
          ])
        }

      } else {
        setlistItem([
          {
            title: 'Poin',
            target: 'Rp,15.500.000',
            icon: 'ic_share_coint',
            flag: 'foco_point'
          },
          {
            title: 'Coin',
            target: 'Rp,17.500.000',
            icon: 'ic_coint',
            flag: 'foco_coint'

          },
          {
            title: 'Saldo',
            target: 'Rp,17.500.000',
            icon: 'ic_box',
            flag: 'saldo'
          }
        ])
      }


      getData(Constants.SESSION_USER_PROFILE).then(res => {
        var params = {
          userid: res ? res.result.hp : '0'
        }
        getPoint(params, res.result.token);
      })
    });
    
  }, []);

 

  const onPressItem =(item)=>{
    if (hub === "COHUB") {

      switch (item.flag) {
        case 'foco_point':
          navigation.navigate(Routers.REWARDS_COMMISION_DETIL_SCREEN, { item })
          break;
        case 'foco_coint':
          navigation.navigate(Routers.REWARDS_COMMISION_DETIL_SCREEN, { item })
          break;
        case 'pencairan':
          navigation.navigate((Routers.PENCAIRAN_SCREEN), { title: "Setoran COD", filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terkirim', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: false })
          break;
        case 'history_pencairan':
          navigation.navigate((Routers.HISTORY_PENCAIRAN_SCREEN), { title: "Setoran COD", filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terkirim', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: false })
          break;
        case 'comition_send':
          navigation.navigate((Routers.COMITSION_COHUB_SCREEN), { title: "Komisi Saya", filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terkirim', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: false })
          break;
        case 'cod':
          navigation.navigate((Routers.COD_CO_HUB), { title: "Komisi Saya", filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terkirim', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: false })
          break;
          

        // case 'tahunan': 
        // navigation.navigate(Routers.TARGET_BONUS_DETIL_SCREEN, {})
        // break;


      }

    } else {

      switch (item.flag) {
        case 'foco_point':
          navigation.navigate(Routers.REWARDS_COMMISION_DETIL_SCREEN, { item })
          break;
        case 'foco_coint':
          navigation.navigate(Routers.REWARDS_COMMISION_DETIL_SCREEN, { item })
          break;
        case 'saldo':
          navigation.navigate(Routers.REWARDS_COMMISION_DETIL_SCREEN, { item })
          break;
        case 'comition_send':
          navigation.navigate((Routers.COMITION), { title: "Komisi Saya", filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terkirim', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: false })
          break;
        case 'pencairan':
          navigation.navigate((Routers.PENCAIRAN_SCREEN), { title: "Setoran COD", filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terkirim', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: false })
          break;
        case 'history_pencairan':
          navigation.navigate((Routers.HISTORY_PENCAIRAN_SCREEN), { title: "Setoran COD", filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terkirim', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: false })
          break;

          case 'cod':
          navigation.navigate((Routers.COD_SCREEN), { title: "Setoran COD", filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terkirim', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: false, search: true })
          break;

          case 'riwayat_cod':
          navigation.navigate((Routers.RIWAYAT_COD_SCREEN), { title: "Setoran COD", filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terkirim', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: false })
          break;

          

        // case 'tahunan': 
        // navigation.navigate(Routers.TARGET_BONUS_DETIL_SCREEN, {})
        // break;


      }
    }
    
  }

  
  const goBack =(item)=>{
    navigation.goBack()
  }


  const getPoint = (params, token) => {
    setLoading(true);
    JSONAxioGet(getURL('get-coint', params), null, token)
      .then(respone => {
        const response = respone.data;
        setLoading(false);

        if (response.statusCode == 1) {
          setDataCoint(response.result);
        } else {
          cekError(response.statusCode, response.message)
        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "Login Kembali",
        statusCode: statusCode
      })
    }
    else if (statusCode == 1) {
      setContentWarning({
        title: "Yeey !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setLoading(false);
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  const actionButton = () => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: "LoginStack" }] });
        });
      });
    }

  }

  return (
    <View style={{flex:1, backgroundColor: Colors.white}}>

      <Toolbar
        switchAccount={switchAccount}
        onPress={goBack}
        title={'Rewards Dan Komisi'} />

      <Account
        key={0}
        onPresSwitch={() => { console.log("") }}
        dataCoint={dataCoint}
        switchAccount={switchAccount}
        navigation={navigation} />
      
      <FlatList
        style={{ marginTop: Scale(20) }}
        showsVerticalScrollIndicator={false}
        showsHorizontalScrollIndicator={false}
        data={listItem}
        renderItem={({ item, index }) => (
          <TouchableOpacity
          onPress={() => onPressItem(item)}>

            <View style ={{borderColor: Colors.gray, borderWidth: Scale(1), borderRadius: Scale(8), marginHorizontal: Scale(16), marginVertical: Scale(8), padding: Scale(16)}}>

              <View style={{ flexDirection: 'row' }}>
                <View style={{ flex: 0.1, justifyContent: 'center', alignItems: 'center' }}>
                  <Image
                    style={{ height: Scale(18), width: Scale(18), tintColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor  }}
                    source={getIcon(item.icon)}
                    resizeMode='contain' />
                </View>

                <View style={{ flex: 1, marginLeft: Scale(20) }}>
                  <View style={{ flexDirection: 'row' }}>
                    <View style={{ flex: 0.8 }}><Text style={[styles.text40012, { marginVertical: Scale(6) }]}>{item.title}</Text></View>
                    {/* <View style={{ flex: 0.1 }}><Text style={[styles.text40012, { marginVertical: Scale(6) }]}>{":"}</Text></View>
                    <View style={{ flex: 1 }}>
                      <Text style={[styles.text40012, { marginVertical: Scale(6), color: switchAccount ? Colors.primaryColorHub : Colors.primaryColor  }]}>{item.target}</Text>

                    </View> */}


                  </View>

                </View>

                <View style={{ flex: 0.1, justifyContent: 'center', alignItems: 'center' }}>
                  <Image
                    style={{ height: Scale(18), width: Scale(18), tintColor : switchAccount ? Colors.primaryColorHub : Colors.primaryColor  }}
                    source={getIcon('ic_arrow_right')}
                    resizeMode='contain' />
                </View>


              </View>

            </View>
          </TouchableOpacity>
        )
        }
      />



      <PopUp
        visible={warning}
        onPressButton={() => {actionButton() }}
        title={contentWarning?.title}
        desc={contentWarning?.desc}
        titleButton={contentWarning?.titleButton} />

    </View>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  text400: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
  text600: { color: Colors.black, fontWeight: '600', fontSize: Scale(14) },
  text40012: { color: Colors.black, fontWeight: '400', fontSize: Scale(12) },
});
export default RewardsComision;